content.content:
"use client";

// Cyrus v4 (owner concept, 2026-10-07): the AI mod studio inside the normal portal frame
// (the portal's own sidebar and top bar stay; Cyrus fills the content area).
//   top-left the projects switcher (per game, Custom Project, Cyrus Pro) + find / new
//   stage   the web: Cyrus core -> game -> mod category -> mod, neon threads in deep space
//   right   the inspector for the selected mod (Code / Explain / Versions / Files / Notes)
//   bottom  the composer (Chat / Generate / Debug / Refactor / Docs)
import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import { usePathname } from "next/navigation";
import { isTerminal, type ModBuildView } from "@/lib/modbuilder/types";
import type { MbServer } from "@/lib/modbuilder/install";
import { CYRUS_DEFAULT_MODEL, type CyrusModelId } from "@/lib/cyrus/models";
import { groupProjects, projectOf, viewMeta, versionNumber, type CyrusProject } from "@/lib/cyrus/projects";
import { CYRUS_TEMPLATES, type CyrusTemplate } from "@/lib/cyrus/templates";
import { CYRUS_DEFAULT_GAME, cyrusGame } from "@/lib/cyrus/games";
import { cyrusCategory, type CyrusCategoryId } from "@/lib/cyrus/categories";
import type { CyrusMeta } from "@/lib/cyrus/meta";
import { Composer, type ComposerHandle, type ComposerMode, type ComposerSubmit } from "./Composer";
import { Inspector, type Tab } from "./Inspector";
import { Switcher } from "./Switcher";
import { Stage } from "./Stage";
import { InfoModal, SearchPalette, ShortcutsModal, TemplateLibrary } from "./Modals";
import { CyIcon, NeonDefs } from "./icons";
import { useLive } from "./useLive";
import type { CyrusTree } from "./web/tree";
import { buildTree, pathTo, type TreeNode } from "./web/tree-layout";
import { eventAction } from "./web/scenes";
import { isTypingTarget } from "./util";
import { CyrusTokensHost, cyrusTokens, useCyrusTokens } from "@/components/cyrus-tokens";

const BASE = "/dashboard/cyrus";
type Toast = { id: string; text: string; buildId?: string; ok: boolean };

export function CyrusApp({ initialBuilds, servers, online, firstName, email }: { initialBuilds: ModBuildView[]; servers: MbServer[]; online: boolean; firstName: string; email?: string }) {
  const [builds, setBuilds] = useState<ModBuildView[]>(initialBuilds);
  const [netErr, setNetErr] = useState(false);
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [modal, setModal] = useState<null | "search" | "keys" | "templates" | "pro" | "addgame">(null);
  const [tab, setTab] = useState<Tab>("code");
  const [focusPath, setFocusPath] = useState<string | null>(null);
  const [hoverNode, setHoverNode] = useState<string | null>(null);
  const [wide, setWide] = useState(false);
  const pathname = usePathname();
  const routeId = pathname.startsWith(BASE + "/") ? decodeURIComponent(pathname.slice(BASE.length + 1).split("/")[0]) : null;
  const composer = useRef<ComposerHandle>(null);
  const engine = useRef<CyrusTree | null>(null);
  const root = useRef<HTMLDivElement>(null);

  const projects = useMemo(() => groupProjects(builds), [builds]);
  // No mod in the URL: the inspector shows the mod that matters now (building, else most recent).
  const routed = projectOf(projects, routeId);
  const project = routed ?? (routeId ? null : projects[0] ?? null);
  const viewing = routed ? routed.builds.find((b) => b.id === routeId) ?? null : project ? (project.running ?? project.head ?? project.latest) : null;
  const inflight = builds.filter((b) => !isTerminal(b.status)).length;
  const toast = useCallback((text: string, extra: Partial<Toast> = {}) => setToasts((t) => [...t, { id: Math.random().toString(36).slice(2), text, ok: true, ...extra }]), []);

  const go = useCallback((id: string | null) => {
    const url = id ? `${BASE}/${id}` : BASE;
    if (url !== window.location.pathname) window.history.pushState(null, "", url);
  }, []);
  const openProject = useCallback((p: CyrusProject) => { go((p.running ?? p.head ?? p.latest).id); }, [go]);

  const lastRoot = useRef<string | null>(null);
  useEffect(() => {
    if (!project) { lastRoot.current = null; return; }
    if (lastRoot.current !== project.rootId) { setTab("code"); setFocusPath(null); }
    lastRoot.current = project.rootId;
  }, [project]);

  const viewingRef = useRef<string | null>(null);
  viewingRef.current = viewing?.id ?? null;
  const upsert = useCallback((list: ModBuildView[]) => {
    setBuilds((cur) => {
      const m = new Map(cur.map((b) => [b.id, b]));
      for (const b of list) {
        const prev = m.get(b.id);
        if (prev && !isTerminal(prev.status) && isTerminal(b.status)) {
          if (b.status === "succeeded" && viewingRef.current === b.id) engine.current?.bloom();
          if (viewingRef.current !== b.id) setToasts((t) => [...t.filter((x) => x.buildId !== b.id), { id: b.id + b.status, buildId: b.id, ok: b.status === "succeeded", text: b.status === "succeeded" ? `${b.pluginName || "Your mod"} is ready` : `${b.pluginName || "A build"} didn't build` }]);
        }
        m.set(b.id, { ...prev, ...b });
      }
      return Array.from(m.values());
    });
  }, []);

  // Poll every in-flight build (each GET also syncs it from the build service).
  useEffect(() => {
    const ids = builds.filter((b) => !isTerminal(b.status)).map((b) => b.id);
    if (!ids.length) return;
    let stop = false;
    const t = setTimeout(async () => {
      const res = await Promise.all(ids.map((id) => fetch(`/api/mod-builder/builds/${id}`, { cache: "no-store" }).then((r) => (r.ok ? r.json() : null)).catch(() => null)));
      if (stop) return;
      upsert(res.filter(Boolean).map((j) => j.build as ModBuildView));
      setNetErr(res.some((r) => !r));
    }, document.visibilityState === "hidden" ? 9000 : 2000);
    return () => { stop = true; clearTimeout(t); };
  }, [builds, upsert]);
  const refreshAll = useCallback(async () => {
    const r = await fetch("/api/mod-builder/builds", { cache: "no-store" }).catch(() => null);
    if (r?.ok) { const j = await r.json(); upsert(j.builds as ModBuildView[]); }
  }, [upsert]);
  useEffect(() => { const t = setInterval(refreshAll, 30_000); return () => clearInterval(t); }, [refreshAll]);
  useEffect(() => { if (!toasts.length) return; const t = setTimeout(() => setToasts((x) => x.slice(1)), 6000); return () => clearTimeout(t); }, [toasts]);

  const create = useCallback(async (body: Record<string, unknown>): Promise<string | null> => {
    try {
      const r = await fetch("/api/mod-builder/builds", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) { cyrusTokens.handleBuildError(j); return j.error || "Cyrus couldn't start this build."; }
      void cyrusTokens.refresh();
      upsert([j.build]);
      go(j.build.id);
      return null;
    } catch { return "We couldn't reach Nxeon. Check your connection and try again."; }
  }, [go, upsert]);

  const patch = useCallback(async (rootId: string, p: Record<string, unknown>): Promise<string | null> => {
    setBuilds((cur) => cur.map((b) => (b.id === rootId ? { ...b, cyrus: { ...viewMeta(b), ...cleanPatch(p) } } : b)));
    try {
      const r = await fetch(`/api/mod-builder/projects/${rootId}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify(p) });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) { refreshAll(); return j.error || "Couldn't save."; }
      setBuilds((cur) => cur.map((b) => (b.id === rootId ? { ...b, cyrus: j.meta } : b)));
      return null;
    } catch { return "Couldn't save."; }
  }, [refreshAll]);

  const duplicate = useCallback(async (p: CyrusProject) => {
    const src = p.head ?? p.latest;
    return create({ prompt: (p.builds[0] ?? src).prompt, mcVersion: src.mcVersion, model: viewMeta(src).model ?? CYRUS_DEFAULT_MODEL });
  }, [create]);

  // ----- the composer: Generate = new mod; the other modes build the next version ---------
  const base = project ? (viewing?.status === "succeeded" ? viewing : project.head) : null;
  const target = project && base ? { title: project.title, version: base.mcVersion, n: versionNumber(project, base.id) } : null;
  const submit = useCallback(async (s: ComposerSubmit) => {
    if (s.mode === "generate") return create({ prompt: s.text, mcVersion: s.mcVersion, model: s.model, attachmentIds: s.attachmentIds });
    if (!base || !project) return "Pick a mod on the web first.";
    if (project.running) return `Cyrus is building v${versionNumber(project, project.running.id)}. Ask for the next change when it's done.`;
    return create({ baseBuildId: base.id, changeRequest: s.text, model: s.model, attachmentIds: s.attachmentIds });
  }, [create, base, project]);
  const busyReason = inflight >= 2 ? "Two mods are building. Cyrus builds two at a time in the preview." : !online ? "The builder is offline right now. Write your idea; building resumes shortly." : null;
  const newMod = useCallback((prefill?: { text: string; model?: CyrusModelId }) => {
    composer.current?.setText(prefill?.text ?? "", prefill?.model, "generate");
  }, []);
  const useTemplate = useCallback((t: CyrusTemplate) => { setModal(null); newMod({ text: t.prompt, model: t.model }); }, [newMod]);

  // ----- the web ---------------------------------------------------------------------------
  const model = useMemo(() => buildTree(projects, CYRUS_TEMPLATES, { selectedRoot: project?.rootId ?? null }), [projects, project?.rootId]);
  const selPath = useMemo(() => (project ? pathTo(model, `m:${project.rootId}`) : []), [model, project]);
  const runPaths = useMemo(() => projects.filter((p) => p.running).map((p) => pathTo(model, `m:${p.rootId}`)).filter((p) => p.length), [projects, model]);
  const hoverPath = useMemo(() => (hoverNode ? pathTo(model, hoverNode) : []), [model, hoverNode]);

  const selRef = useRef(selPath);
  selRef.current = selPath;
  const live = useLive(viewing && !isTerminal(viewing.status) ? viewing : null, (_path, n) => {
    if (selRef.current.length) engine.current?.emit(selRef.current, Math.min(2, Math.ceil(n / 400)));
  });
  // real build events -> light down the branch
  const seenEv = useRef<{ id: string; n: number } | null>(null);
  useEffect(() => {
    if (!viewing) { seenEv.current = null; return; }
    const ev = viewing.result?.events ?? [];
    const prev = seenEv.current;
    seenEv.current = { id: viewing.id, n: ev.length };
    if (!prev || prev.id !== viewing.id) return;
    for (const x of ev.slice(prev.n)) {
      const a = eventAction(x.message, x.stage);
      if (!a) continue;
      if (a.kind === "bloom") engine.current?.bloom();
      else engine.current?.emit(selRef.current, a.kind === "gather" || a.kind === "scan" ? 3 : 1);
    }
  }, [viewing]);

  const onActivity = useCallback((a: { typing: boolean; listening: boolean; level: number }) => {
    engine.current?.setEnergy(a.listening ? 0.25 + a.level * 0.75 : a.typing ? 0.55 : 0);
  }, []);

  const onNode = useCallback((n: TreeNode) => {
    if (n.kind === "mod") { const p = projects.find((x) => x.rootId === n.ref); if (p) openProject(p); }
    else if (n.kind === "tpl") { const t = CYRUS_TEMPLATES.find((x) => x.id === n.ref); if (t) useTemplate(t); }
    else if (n.kind === "start") { const c = cyrusCategory(n.ref as CyrusCategoryId); newMod({ text: `A ${c.name.toLowerCase()} mod that ` }); }
    else if (n.kind === "more") setModal("search");
    else if (n.kind === "add") setModal("addgame");
    else if (n.kind === "game") { if (n.soon) toast(`${n.label} mods are coming soon. Cyrus builds Minecraft plugins today.`); engine.current?.focusNode(n.id); }
    else if (n.kind === "cat") engine.current?.focusNode(n.id);
  }, [projects, openProject, useTemplate, newMod, toast]);

  // where the web sits: between the sidebar and the inspector, under the top bar, above the composer
  const [region, setRegion] = useState({ x: 0, y: 0, w: 1000, h: 700 });
  const measure = useCallback(() => {
    const r = root.current?.querySelector(".cy-stage")?.getBoundingClientRect();
    if (!r) return;
    const ins = root.current?.querySelector(".cy-insp")?.getBoundingClientRect();
    const cmp = root.current?.querySelector(".cy-dockc")?.getBoundingClientRect();
    const narrow = r.width < 900;
    const right = !narrow && ins ? ins.left - r.left - 8 : r.width;
    const bottom = !narrow && cmp ? cmp.top - r.top - 4 : Math.min(r.height, 560);
    const next = { x: 0, y: 64, w: Math.max(200, right), h: Math.max(200, bottom - 64) };
    setRegion((o) => (Math.abs(o.x - next.x) + Math.abs(o.y - next.y) + Math.abs(o.w - next.w) + Math.abs(o.h - next.h) < 2 ? o : next));
  }, []);
  useLayoutEffect(() => {
    measure();
    const ro = new ResizeObserver(() => measure());
    if (root.current) ro.observe(root.current);
    const t = setTimeout(measure, 300);
    return () => { ro.disconnect(); clearTimeout(t); };
  }, [measure, wide, project?.rootId]);

  // global shortcuts
  useEffect(() => {
    const k = (e: KeyboardEvent) => {
      if (e.key === "Escape" && modal) { setModal(null); return; }
      if (isTypingTarget(e.target) || e.metaKey || e.ctrlKey || e.altKey || modal) return;
      const idx = project ? projects.findIndex((p) => p.rootId === project.rootId) : -1;
      switch (e.key) {
        case "n": case "N": e.preventDefault(); newMod(); break;
        case "p": case "P": e.preventDefault(); setModal("search"); break;
        case "?": e.preventDefault(); setModal("keys"); break;
        case "/": e.preventDefault(); composer.current?.focus(); break;
        case "v": case "V": e.preventDefault(); composer.current?.toggleVoice(); break;
        case "0": e.preventDefault(); engine.current?.recenter(); break;
        case "+": case "=": e.preventDefault(); engine.current?.zoomBy(1.2); break;
        case "-": e.preventDefault(); engine.current?.zoomBy(0.83); break;
        case "[": if (projects.length) { e.preventDefault(); openProject(projects[(idx - 1 + projects.length) % projects.length]); } break;
        case "]": if (projects.length) { e.preventDefault(); openProject(projects[(idx + 1) % projects.length]); } break;
      }
    };
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  }, [modal, project, projects, newMod, openProject]);

  const retry = async () => viewing ? create(viewing.baseBuildId
    ? { baseBuildId: viewing.baseBuildId, changeRequest: viewing.changeRequest, model: viewMeta(viewing).model }
    : { prompt: viewing.prompt, mcVersion: viewing.mcVersion, model: viewMeta(viewing).model }) : null;
  const editRetry = () => {
    if (!viewing) return;
    const m = viewMeta(viewing).model;
    if (viewing.baseBuildId) { go(viewing.baseBuildId); composer.current?.setText(viewing.changeRequest || "", m, "chat"); }
    else newMod({ text: viewing.prompt, model: m });
  };
  const counts = { [CYRUS_DEFAULT_GAME.id]: projects.length };
  // Cyrus Pro "Upgrade" = the token plans when this account is in the token economy.
  const tokens = useCyrusTokens();
  const defaultMode: ComposerMode = target ? "chat" : "generate";

  return (
    <div ref={root} className="cy-app" data-status={viewing?.status ?? "none"}>
      <NeonDefs />
      <div className="cy-main">
        <Stage engineRef={engine} model={model} selected={selPath} running={runPaths} hover={hoverPath} onNode={onNode}
               onHover={(n) => setHoverNode(n && n.kind !== "core" ? n.id : null)} region={region} building={inflight} />
        <Switcher game={CYRUS_DEFAULT_GAME.id} counts={counts} building={inflight} onSearch={() => setModal("search")}
                  onGame={(id) => { engine.current?.focusNode(`g:${id}`); if (cyrusGame(id).status !== "live") toast(`${cyrusGame(id).name} mods are coming soon.`); }}
                  onNew={() => newMod()} onCustom={() => setModal("templates")} onUpgrade={() => (tokens.state?.active ? cyrusTokens.open({ tab: "plans" }) : setModal("pro"))} />
        {(netErr || !online) && <p className="cy-net"><CyIcon name="warn" size={14} /> {netErr ? "Reconnecting…" : "The builder is offline. Your ideas wait here; building resumes shortly."}</p>}
        <Inspector project={project} viewing={viewing} servers={servers} live={live} tab={tab} setTab={setTab} focusPath={focusPath} onPickFile={setFocusPath}
                   onOpen={(id) => go(id)} onPatch={patch} onDuplicate={duplicate} onRefresh={refreshAll} onRetry={retry} onEdit={editRetry}
                   onOpenProject={(p) => { engine.current?.focusNode(`m:${p.rootId}`); setTab("files"); }} onUseTemplate={useTemplate} onToast={(t) => toast(t)}
                   wide={wide} onWide={() => setWide((w) => !w)} />
        <div className="cy-dockc">
          <Composer ref={composer} target={target} defaultMode={defaultMode} defaultModel={(viewing && viewMeta(viewing).model) || CYRUS_DEFAULT_MODEL}
                    disabledReason={busyReason} onSubmit={submit} onActivity={onActivity} game={CYRUS_DEFAULT_GAME} />
          <p className="cy-legal">Cyrus builds Paper server plugins (Java). Not an official Minecraft product. Not approved by or associated with Mojang or Microsoft.</p>
        </div>
        <div className="cy-webctl" aria-label="Network view">
          <button type="button" onClick={() => engine.current?.zoomBy(1.2)} aria-label="Zoom in" title="Zoom in  +"><CyIcon name="plus" size={14} /></button>
          <button type="button" onClick={() => engine.current?.zoomBy(0.83)} aria-label="Zoom out" title="Zoom out  −"><CyIcon name="minus" size={14} /></button>
          <button type="button" onClick={() => engine.current?.recenter()} aria-label="Recenter" title="Recenter  0"><CyIcon name="recenter" size={14} /></button>
        </div>
      </div>

      <CyrusTokensHost />
      <div className="cy-toasts" aria-live="polite">
        {toasts.map((t) => (
          <button key={t.id} type="button" className={`cy-toast ${t.ok ? "ok" : "bad"}`} onClick={() => { if (t.buildId) go(t.buildId); setToasts((x) => x.filter((y) => y.id !== t.id)); }}>
            <span className="cy-toast-orb"><CyIcon name={t.ok ? "check" : "warn"} size={13} strokeWidth={2.2} /></span>
            <span>{t.text}</span>{t.buildId && <span className="cy-toast-go">Open <CyIcon name="chevr" size={12} /></span>}
          </button>
        ))}
      </div>

      {modal === "search" && <SearchPalette projects={projects} onClose={() => setModal(null)} onPick={(p) => { setModal(null); openProject(p); }}
                                             onFile={(id, path) => { setModal(null); go(id); setTab("code"); setFocusPath(path); }}
                                             onGame={(id) => { setModal(null); engine.current?.focusNode(`g:${id}`); }}
                                             onAsk={(q) => { setModal(null); newMod({ text: q }); }} />}
      {modal === "keys" && <ShortcutsModal onClose={() => setModal(null)} />}
      {modal === "templates" && <TemplateLibrary onClose={() => setModal(null)} onUse={useTemplate} />}
      {(modal === "pro" || modal === "addgame") && <InfoModal kind={modal === "pro" ? "pro" : "addgame"} onClose={() => setModal(null)} />}
    </div>
  );
}

function cleanPatch(p: Record<string, unknown>): Partial<CyrusMeta> {
  const o: Record<string, unknown> = { ...p };
  for (const k of Object.keys(o)) if (o[k] === null) delete o[k];
  return o as Partial<CyrusMeta>;
}
"use client";

// Live code for a running build (service modbuilder:0.4+, proxied by
// /api/mod-builder/builds/:id/live). Polls with diffing:
//  - files: src/main/** with a short content hash; only changed files are re-fetched;
//  - draft: the file the AI is writing RIGHT NOW, streamed from its partial tool input;
//    the request carries (path, seq, from) so only the unseen tail comes back.
// An older service answers live:false; the UI then falls back to file names from events.
import { useEffect, useRef, useState } from "react";
import { isTerminal, type ModBuildView } from "@/lib/modbuilder/types";

export type LiveFileState = "writing" | "editing" | "written" | "edited";
export type LiveFile = { path: string; text: string | null; prev: string | null; state: LiveFileState; changedAt: number };
export type LiveDraft = { path: string; seq: number; op: "write" | "edit"; text: string; done: boolean };
export type LiveState = { supported: boolean | null; files: Map<string, LiveFile>; draft: LiveDraft | null; tick: number };

type Resp = { live: boolean; files: { path: string; size: number; hash: string }[]; draft: { path: string; op: "write" | "edit"; seq: number; from: number; text: string; total: number; done: boolean } | null };

export function useLive(build: ModBuildView | null, onChars?: (path: string, n: number) => void): LiveState {
  const running = !!build && !isTerminal(build.status);
  const buildId = build?.id ?? null;
  const [state, setState] = useState<LiveState>({ supported: null, files: new Map(), draft: null, tick: 0 });
  const files = useRef(new Map<string, LiveFile & { hash: string }>());
  const draft = useRef<LiveDraft | null>(null);
  const supported = useRef<boolean | null>(null);
  const cb = useRef(onChars);
  cb.current = onChars;

  useEffect(() => {
    files.current = new Map(); draft.current = null; supported.current = null;
    setState({ supported: null, files: new Map(), draft: null, tick: 0 });
  }, [buildId]);

  useEffect(() => {
    if (!running || !buildId) return;
    let stop = false;
    let timer: number | undefined;
    const id = buildId;
    const poll = async () => {
      if (stop) return;
      const d = draft.current;
      const q = d && !d.done ? `?draft=${encodeURIComponent(d.path)}&seq=${d.seq}&from=${d.text.length}` : "";
      let wait = 1200;
      try {
        const r = await fetch(`/api/mod-builder/builds/${id}/live${q}`, { cache: "no-store" });
        const j = (r.ok ? await r.json() : null) as Resp | null;
        if (stop) return;
        if (j && j.live) {
          supported.current = true;
          // 1) the file being streamed right now
          if (j.draft) {
            const x = j.draft;
            const cur = draft.current;
            let added = 0;
            if (cur && cur.path === x.path && cur.seq === x.seq) {
              const base = x.from <= cur.text.length ? cur.text.slice(0, x.from) : cur.text;
              added = Math.max(0, base.length + x.text.length - cur.text.length);
              draft.current = { ...cur, text: base + x.text, done: x.done };
            } else {
              // a new tool call (the server answers from 0 whenever path or seq differ)
              draft.current = { path: x.path, seq: x.seq, op: x.op, text: x.text, done: x.done };
              added = x.text.length;
            }
            if (added > 0) cb.current?.(x.path, added);
            wait = x.done ? 900 : 550;
          } else if (draft.current && !draft.current.done) {
            draft.current = { ...draft.current, done: true };
          }
          // 2) files that landed or changed in the workspace: show them at once, contents follow
          const changed = j.files.filter((f) => files.current.get(f.path)?.hash !== f.hash);
          const publish = () => {
            const dd = draft.current;
            const view = new Map<string, LiveFile>();
            for (const [p, f] of files.current) view.set(p, f);
            if (dd && !dd.done) {
              const f = view.get(dd.path);
              view.set(dd.path, { path: dd.path, text: f?.text ?? null, prev: f?.prev ?? null, state: dd.op === "edit" ? "editing" : "writing", changedAt: Date.now() });
            }
            setState((s) => ({ supported: true, files: view, draft: dd ? { ...dd } : null, tick: s.tick + 1 }));
          };
          for (const f of changed) {
            const prev = files.current.get(f.path);
            // a file the draft just finished keeps the streamed text until the real one arrives
            const streamed = draft.current && draft.current.path === f.path ? draft.current.text : null;
            files.current.set(f.path, { path: f.path, hash: f.hash, text: prev?.text ?? streamed, prev: prev?.text ?? null, state: prev ? "edited" : "written", changedAt: Date.now() });
          }
          publish();
          if (changed.length) {
            await Promise.all(changed.map(async (f) => {
              const t = await fetch(`/api/mod-builder/builds/${id}/source?path=${encodeURIComponent(f.path)}`, { cache: "no-store" }).then((x) => (x.ok ? x.text() : null)).catch(() => null);
              const cur = files.current.get(f.path);
              if (cur && t !== null) files.current.set(f.path, { ...cur, text: t });
            }));
            if (stop) return;
            publish();
          }
        } else if (j && !j.live) {
          if (supported.current === null) { supported.current = false; setState((s) => ({ ...s, supported: false })); }
          wait = 2500;
        }
      } catch { wait = 3000; }
      if (document.visibilityState === "hidden") wait = Math.max(wait, 4000);
      timer = window.setTimeout(poll, wait);
    };
    poll();
    return () => { stop = true; window.clearTimeout(timer); };
  }, [running, buildId]);

  return state;
}

/** Smooth "typing": reveals `target` at the rate it arrives, catching up within ~0.9 s. */
export function useTypewriter(target: string, key: string, active: boolean): number {
  const [shown, setShown] = useState(target.length);
  const s = useRef(target.length);
  const k = useRef(key);
  const tgt = useRef(target);
  tgt.current = target;
  useEffect(() => {
    if (k.current !== key) { k.current = key; s.current = 0; setShown(0); }
  }, [key]);
  useEffect(() => {
    if (!active) { s.current = tgt.current.length; setShown(s.current); return; }
    if (typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches) { s.current = tgt.current.length; setShown(s.current); return; }
    let raf = 0, last = performance.now(), acc = 0;
    const step = (now: number) => {
      const dt = Math.min(0.1, (now - last) / 1000); last = now;
      const n = tgt.current.length;
      if (s.current > n) s.current = n;
      const backlog = n - s.current;
      if (backlog > 0) {
        s.current = Math.min(n, s.current + Math.max(70, backlog / 0.9) * dt);
        acc += dt;
        if (acc > 0.045) { acc = 0; setShown(Math.floor(s.current)); }
      }
      raf = requestAnimationFrame(step);
    };
    raf = requestAnimationFrame(step);
    return () => cancelAnimationFrame(raf);
  }, [active]);
  return Math.min(shown, target.length);
}

