/** Pick the category whose words appear most in the text (title words count double). */
export function classifyMod(parts: { title?: string | null; text?: string | null }): CyrusCategoryId {
  const title = parts.title || "";
  const text = parts.text || "";
  let best: CyrusCategoryId = "other", score = 0;
  for (const c of CYRUS_CATEGORIES) {
    if (c.id === "other") continue;
    const g = new RegExp(c.words.source, "gi");
    const n = (title.match(g)?.length ?? 0) * 2 + (text.match(g)?.length ?? 0);
    if (n > score) { score = n; best = c.id; }
  }
  return best;
}

