198	function BuildStrip({ b }: { b: ModBuildView }) {
199	  const events = b.result?.events ?? [];
200	  const startedAt = events.find((e) => e.stage !== "queued")?.at ?? null;
201	  const [now, setNow] = useState(() => Date.now());
202	  useEffect(() => { const t = setInterval(() => setNow(Date.now()), 1000); return () => clearInterval(t); }, []);
203	  const order = ["planning", "coding", "compiling", "repairing", "scanning", "succeeded"];
204	  const cur = order.indexOf(b.status === "queued" ? "planning" : b.status);
205	  const repairs = b.result?.repairs ?? 0;
206	  const stream = events.filter((e) => e.stage !== "queued" && e.message && e.message !== "Error details" && e.message !== "API lookup").slice(-3);
207	  const head = b.status === "queued" && b.result?.queuePosition ? `In line · position ${b.result.queuePosition}` : STAGE_HEADLINE[b.status] ?? "Working";
208	  return (
209	    <div className="cy-strip-b" aria-live="polite">
210	      <div className="cy-stages">
211	        {CYRUS_STAGES.map((st, i) => {
212	          const state = i < cur ? (st.key === "repairing" && !repairs ? "skip" : "done") : i === cur ? "now" : "todo";
213	          return <span key={st.key} className={`cy-stg ${state}`} title={st.sub}><i />{st.label}</span>;
214	        })}
215	      </div>
216	      <p className="cy-strip-h"><i className="cy-dotpulse" /> {head}{b.status === "repairing" && repairs ? ` · fix ${repairs} of 3` : ""} <span suppressHydrationWarning>{startedAt ? dur(now - new Date(startedAt).getTime()) : ""}</span></p>
217	      {stream.length > 0 && (
218	        <ol className="cy-thoughts">
219	          {stream.map((e, i) => <li key={`${e.at}-${i}`}><span className="t" suppressHydrationWarning>+{Math.max(0, Math.round((new Date(e.at).getTime() - new Date(startedAt || e.at).getTime()) / 1000))}s</span> {e.message}</li>)}
220	        </ol>
221	      )}
222	      <p className="cy-fine">{CYRUS_STATUS_LABEL[b.status]} · the code above types itself out as Cyrus writes it.</p>
