632	function LevelMeter({ level }: { level: React.MutableRefObject<number> }) {
633	  const box = useRef<HTMLSpanElement>(null);
634	  useEffect(() => {
635	    const bars = Array.from(box.current?.children || []) as HTMLElement[];
636	    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
637	    const shape = [0.55, 0.8, 1, 0.8, 0.55];
638	    let raf = 0, last = 0, smooth = 0;
639	    const tick = (now: number) => {
640	      raf = requestAnimationFrame(tick);
641	      if (now - last < 60) return;
642	      last = now;
643	      smooth += (Math.min(1, level.current * 1.6) - smooth) * 0.35;
644	      const idle = 0.22 + 0.06 * Math.sin(now / 520);
645	      bars.forEach((b, i) => { b.style.transform = `scaleY(${Math.max(idle, 0.2 + smooth * shape[i] * 0.8).toFixed(3)})`; });
646	    };
647	    if (reduce) bars.forEach((b) => { b.style.transform = "scaleY(.5)"; });
648	    else raf = requestAnimationFrame(tick);
649	    return () => cancelAnimationFrame(raf);
650	  }, [level]);
651	  return <span ref={box} className="cy-level" aria-hidden="true">{Array.from({ length: 5 }, (_, i) => <i key={i} />)}</span>;
