import { forgeStream, type ForgeRequest } from "@/lib/engine";
import { CATEGORY_BY_KEY, EMBLEMS, MAX_GAMES, MODEL_BY_ID, TEMPLATES } from "@/lib/data";
import type { Game } from "@/lib/types";

const str = (v: unknown, max: number) => (typeof v === "string" ? v.slice(0, max) : "");

/** Only well-formed user-added games get through; everything is clamped. */
function cleanGames(input: unknown): Game[] {
  if (!Array.isArray(input)) return [];
  return input
    .slice(0, MAX_GAMES)
    .filter((g) => g && typeof g === "object" && typeof g.id === "string" && g.id.startsWith("custom-"))
    .map((g) => {
      const template = TEMPLATES.find((t) => t.key === g.template) ?? TEMPLATES[0];
      const categories = (Array.isArray(g.categories) ? g.categories : []).filter((c: string) => c in CATEGORY_BY_KEY).slice(0, 6);
      return {
        id: str(g.id, 80),
        name: str(g.name, 40) || "Custom game",
        short: str(g.short, 16) || "Custom",
        toolchain: str(g.toolchain, 40) || template.toolchain,
        language: template.language,
        rgb: /^\d{1,3} \d{1,3} \d{1,3}$/.test(g.rgb) ? g.rgb : "167 139 250",
        emblem: EMBLEMS.includes(g.emblem) ? g.emblem : "cube",
        blurb: str(g.blurb, 120),
        aliases: (Array.isArray(g.aliases) ? g.aliases : []).map((a: unknown) => str(a, 40).toLowerCase()).filter(Boolean).slice(0, 6),
        categories: categories.length ? categories : ["mechanics"],
        template: template.key,
        custom: true,
      } satisfies Game;
    });
}

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

export async function POST(req: Request) {
  let body: ForgeRequest;
  try {
    body = (await req.json()) as ForgeRequest;
  } catch {
    return Response.json({ error: "Invalid JSON body" }, { status: 400 });
  }
  if (!body?.prompt || typeof body.prompt !== "string" || !body.prompt.trim()) {
    return Response.json({ error: "Prompt is required" }, { status: 400 });
  }
  if (!MODEL_BY_ID[body.model]) {
    return Response.json({ error: `Unknown model "${body.model}"` }, { status: 400 });
  }

  body.games = cleanGames(body.games);

  const encoder = new TextEncoder();
  const abort = new AbortController();
  req.signal.addEventListener("abort", () => abort.abort());

  const stream = new ReadableStream<Uint8Array>({
    async start(controller) {
      try {
        for await (const event of forgeStream(body, abort.signal)) {
          controller.enqueue(encoder.encode(JSON.stringify(event) + "\n"));
        }
      } catch (err) {
        if (!abort.signal.aborted) {
          const message = err instanceof Error ? err.message : "The forge collapsed unexpectedly";
          controller.enqueue(encoder.encode(JSON.stringify({ type: "error", message }) + "\n"));
        }
      } finally {
        try {
          controller.close();
        } catch {
          /* already closed by a client abort */
        }
      }
    },
    cancel() {
      abort.abort();
    },
  });

  return new Response(stream, {
    headers: {
      "Content-Type": "application/x-ndjson; charset=utf-8",
      // no-transform keeps the dev server's gzip from buffering the stream.
      "Cache-Control": "no-cache, no-transform",
      "X-Accel-Buffering": "no",
    },
  });
}
