    models: MODELS,
    mods: SEED_MODS.map(({ versions: _versions, ...m }) => m),
  });
}
"use client";

import { useEffect } from "react";
import { AddGameDialog } from "@/components/chrome/AddGameDialog";
import { CommandPalette } from "@/components/chrome/CommandPalette";
import { Toasts, ZoomControls } from "@/components/chrome/Overlays";
import { TopBar } from "@/components/chrome/TopBar";
import { CosmosBackground } from "@/components/cosmos/CosmosBackground";
import { Network } from "@/components/cosmos/Network";
import { PreviewPanel } from "@/components/preview/PreviewPanel";
import { PromptDock } from "@/components/prompt/PromptDock";
import { useStore } from "@/lib/store";

export function CyrusApp() {
  useEffect(() => {
    // Persisted state loads after hydration so server and client markup match.
    useStore.persist.rehydrate();
    const theme = document.documentElement.classList.contains("light") ? "light" : "dark";
    useStore.setState({ theme });

    const onKey = (e: KeyboardEvent) => {
      const s = useStore.getState();
      const target = e.target as HTMLElement | null;
      const typing = !!target && (target.tagName === "INPUT" || target.tagName === "TEXTAREA" || target.isContentEditable);
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") {
        e.preventDefault();
        s.setPaletteOpen(!s.paletteOpen);
        return;
      }
      if (s.paletteOpen || s.addGameOpen) return;
      if (e.key === "Escape") {
        if (typing) {
          target?.blur();
          return;
        }
        if (s.selection.level !== "core") s.goUp();
        else if (s.panelOpen) s.setPanelOpen(false);
        return;
      }
      if (typing) return;
      if (e.key === "/") {
        e.preventDefault();
        s.focusPrompt();
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  return (
    <main className="fixed inset-0 overflow-hidden">
      <CosmosBackground />
      <Network />
      <TopBar />
      <ZoomControls />
      <PreviewPanel />
      <PromptDock />
      <CommandPalette />
      <AddGameDialog />
      <Toasts />
    </main>
  );
}
export type ModelId = "katara" | "sokka" | "yako";

export type CategoryKey =
  | "weapons"
  | "creatures"
  | "worlds"
  | "mechanics"
  | "shaders"
  | "magic"
  | "quests"
  | "interface"
  | "audio"
  | "vehicles"
  | "items"
  | "characters";

/** Built-in ids are "minecraft", "palworld", "rust", "valheim", "zomboid", "terraria"; user-added games get "custom-…" ids. */
export type GameId = string;

/** Which code generator a game's mods are written with. */
export type TemplateKey = "fabric" | "papyrus" | "smapi" | "tmodloader" | "cet" | "oxide" | "bepinex" | "zomboid" | "ue4ss";

export type EmblemKey = "cube" | "dragon" | "sprout" | "tree" | "chip";

export interface Game {
