import { useMemo } from "react";
import { create } from "zustand";
import { createJSONStorage, persist } from "zustand/middleware";
import { GAMES, GAME_BY_ID, SEED_MODS, categoryNodeId } from "./data";
import { seedVersions } from "./engine";
import type { CategoryKey, Game, GameId, Mod, ModelId, ModFile, ModVersion, Selection } from "./types";

export type PanelTab = "code" | "files" | "versions" | "notes";
export type Theme = "dark" | "light";

export interface ThinkItem {
  id: string;
  label: string;
  detail?: string;
  done: boolean;
  startedAt: number;
  endedAt?: number;
}

export type JobStatus = "connecting" | "thinking" | "writing" | "done" | "error" | "cancelled";

export interface Job {
  id: string;
  status: JobStatus;
  prompt: string;
  model: ModelId;
  images: string[];
  credits: number;
  refining: boolean;
  version: number;
  gameId?: GameId;
  category?: CategoryKey;
  modId?: string;
  modName?: string;
  steps: ThinkItem[];
  files: ModFile[];
  activeFile?: string;
  startedAt: number;
  finishedAt?: number;
  error?: string;
}

export interface Toast {
  id: string;
  title: string;
  body?: string;
  tone: "info" | "success" | "error";
  rgb?: string;
}

export interface FocusTarget {
  kind: "overview" | "node" | "path";
  id?: string;
  tick: number;
}

interface CyrusState {
  theme: Theme;
  userMods: Mod[];
  userVersions: Record<string, ModVersion[]>;
  activeVersion: Record<string, string>;
  notes: Record<string, string>;
  aiNotes: Record<string, string>;
  credits: number;
  model: ModelId;
  /** Branch positions the user dragged, as offsets from each node's parent. Survives reloads. */
  layout: Record<string, [number, number]>;
  /** Game branches the user added themselves. */
  customGames: Game[];
  /** Which core concept renders at the centre of the network (see components/cosmos/cores). */
  coreStyle: string;
  addGameOpen: boolean;

  selection: Selection;
  focus: FocusTarget;
  panelOpen: boolean;
  panelTab: PanelTab;
  activeFile: string | null;
  navOpen: boolean;
  paletteOpen: boolean;
  job: Job | null;
  toasts: Toast[];
  promptFocusTick: number;

  setTheme: (t: Theme) => void;
  toggleTheme: () => void;
  select: (sel: Selection, opts?: { openPanel?: boolean; focus?: FocusTarget["kind"] }) => void;
  goUp: () => void;
  setModel: (m: ModelId) => void;
  setPanelOpen: (open: boolean) => void;
  setPanelTab: (tab: PanelTab) => void;
  setActiveFile: (path: string | null) => void;
  setNavOpen: (open: boolean) => void;
  setPaletteOpen: (open: boolean) => void;
  recenter: () => void;
  toast: (t: Omit<Toast, "id">) => void;
  dismissToast: (id: string) => void;
  setNote: (modId: string, text: string) => void;
  restoreVersion: (modId: string, versionId: string) => void;
  focusPrompt: () => void;
  setNodeHome: (id: string, hx: number, hy: number) => void;
  resetLayout: () => void;
  setAddGameOpen: (open: boolean) => void;
  addGame: (game: Game) => void;
  removeGame: (id: string) => void;
  setCoreStyle: (id: string) => void;
}

export const CORE_ID = "core";

export const useStore = create<CyrusState>()(
  persist(
    (set, get) => ({
      theme: "dark",
      userMods: [],
      userVersions: {},
      activeVersion: {},
      notes: {},
      aiNotes: {},
      credits: 250,
      model: "katara",
      layout: {},
      customGames: [],
      addGameOpen: false,
      coreStyle: "particles",

      selection: { level: "core" },
      focus: { kind: "overview", tick: 0 },
      panelOpen: false,
      panelTab: "code",
      activeFile: null,
      navOpen: false,
      paletteOpen: false,
      job: null,
      toasts: [],
      promptFocusTick: 0,

      setTheme: (theme) => {
        const root = document.documentElement;
        root.classList.add("theme-swap");
        root.classList.remove("dark", "light");
        root.classList.add(theme);
        try {
          localStorage.setItem("cyrus-theme", theme);
        } catch {
          /* private mode */
        }
        window.setTimeout(() => root.classList.remove("theme-swap"), 650);
        set({ theme });
      },
      toggleTheme: () => get().setTheme(get().theme === "dark" ? "light" : "dark"),

      select: (sel, opts) => {
        const focusKind = opts?.focus ?? (sel.level === "core" ? "overview" : "node");
        const id =
          sel.level === "mod"
            ? sel.modId
            : sel.level === "category"
              ? `${sel.gameId}:${sel.category}`
              : sel.level === "game"
                ? sel.gameId
                : CORE_ID;
        set((s) => ({
          selection: sel,
          focus: { kind: focusKind, id, tick: s.focus.tick + 1 },
          panelOpen: opts?.openPanel ?? (sel.level === "mod" ? true : s.panelOpen),
          activeFile: sel.level === "mod" && sel.modId !== s.selection.modId ? null : s.activeFile,
        }));
      },

      goUp: () => {
        const { selection, select } = get();
        if (selection.level === "mod") select({ level: "category", gameId: selection.gameId, category: selection.category });
        else if (selection.level === "category") select({ level: "game", gameId: selection.gameId });
        else select({ level: "core" });
      },

      setModel: (model) => set({ model }),
      setPanelOpen: (panelOpen) => set({ panelOpen }),
      setPanelTab: (panelTab) => set({ panelTab, panelOpen: true }),
      setActiveFile: (activeFile) => set({ activeFile }),
      setNavOpen: (navOpen) => set({ navOpen }),
      setPaletteOpen: (paletteOpen) => set({ paletteOpen }),
      recenter: () => set((s) => ({ focus: { kind: "overview", tick: s.focus.tick + 1 } })),

      toast: (t) => {
        const id = Math.random().toString(36).slice(2);
        set((s) => ({ toasts: [...s.toasts.slice(-3), { ...t, id }] }));
        window.setTimeout(() => get().dismissToast(id), t.tone === "error" ? 6000 : 4200);
      },
      dismissToast: (id) => set((s) => ({ toasts: s.toasts.filter((t) => t.id !== id) })),

      setNote: (modId, text) => set((s) => ({ notes: { ...s.notes, [modId]: text } })),
      restoreVersion: (modId, versionId) => set((s) => ({ activeVersion: { ...s.activeVersion, [modId]: versionId } })),
      focusPrompt: () => set((s) => ({ promptFocusTick: s.promptFocusTick + 1 })),
      setNodeHome: (id, hx, hy) => set((s) => ({ layout: { ...s.layout, [id]: [Math.round(hx), Math.round(hy)] } })),
      resetLayout: () => set({ layout: {} }),
      setAddGameOpen: (addGameOpen) => set({ addGameOpen }),
      setCoreStyle: (coreStyle) => set({ coreStyle }),
      addGame: (game) => set((s) => ({ customGames: [...s.customGames, { ...game, custom: true }] })),
      removeGame: (id) =>
        set((s) => {
          const game = s.customGames.find((g) => g.id === id);
          if (!game) return {};
          const gone = new Set(s.userMods.filter((m) => m.gameId === id).map((m) => m.id));
          const layout = { ...s.layout };
          delete layout[id];
          for (const key of game.categories) delete layout[categoryNodeId(id, key)];
          const strip = <T,>(rec: Record<string, T>) => Object.fromEntries(Object.entries(rec).filter(([k]) => !gone.has(k)));
          return {
            customGames: s.customGames.filter((g) => g.id !== id),
            userMods: s.userMods.filter((m) => m.gameId !== id),
            userVersions: strip(s.userVersions),
            activeVersion: strip(s.activeVersion),
            notes: strip(s.notes),
            aiNotes: strip(s.aiNotes),
            layout,
            selection: s.selection.gameId === id ? ({ level: "core" } as Selection) : s.selection,
          };
        }),
    }),
    {
      name: "cyrus-state-v1",
      storage: createJSONStorage(() => localStorage),
      skipHydration: true,
      partialize: (s) => ({
        userMods: s.userMods,
        userVersions: s.userVersions,
        activeVersion: s.activeVersion,
        notes: s.notes,
        aiNotes: s.aiNotes,
        credits: s.credits,
        model: s.model,
        layout: s.layout,
        customGames: s.customGames,
        coreStyle: s.coreStyle,
      }),
    },
  ),
);

/* ───────────── Derived helpers ───────────── */

/** Built-in or user-added game by id. */
export function getGame(id: GameId | undefined): Game | undefined {
  if (!id) return undefined;
  return GAME_BY_ID[id] ?? useStore.getState().customGames.find((g) => g.id === id);
}

export function useGames(): Game[] {
  const custom = useStore((s) => s.customGames);
  return useMemo(() => [...GAMES, ...custom], [custom]);
}

export function useGame(id: GameId | undefined): Game | undefined {
  const games = useGames();
  return useMemo(() => (id ? games.find((g) => g.id === id) : undefined), [games, id]);
}

const seedCache = new Map<string, ModVersion[]>();

export function versionsOf(mod: Mod | undefined, userVersions: Record<string, ModVersion[]>): ModVersion[] {
  if (!mod) return [];
  let base: ModVersion[] = [];
  if (mod.seed) {
    base = seedCache.get(mod.id) ?? seedVersions(mod);
    seedCache.set(mod.id, base);
  }
  return [...base, ...(userVersions[mod.id] ?? [])];
}

export function useAllMods(): Mod[] {
  const userMods = useStore((s) => s.userMods);
  return useMemo(() => [...SEED_MODS, ...userMods], [userMods]);
}

export function findMod(id: string | undefined): Mod | undefined {
  if (!id) return undefined;
  return SEED_MODS.find((m) => m.id === id) ?? useStore.getState().userMods.find((m) => m.id === id);
}

export function useMod(id: string | undefined) {
  const userMods = useStore((s) => s.userMods);
  return useMemo(() => (id ? (SEED_MODS.find((m) => m.id === id) ?? userMods.find((m) => m.id === id)) : undefined), [id, userMods]);
}

export function useModVersions(mod: Mod | undefined) {
  const userVersions = useStore((s) => s.userVersions);
  const activeVersion = useStore((s) => s.activeVersion);
  return useMemo(() => {
    const versions = versionsOf(mod, userVersions);
    const activeId = mod ? (activeVersion[mod.id] ?? versions[versions.length - 1]?.id) : undefined;
    const active = versions.find((v) => v.id === activeId) ?? versions[versions.length - 1];
    return { versions, active };
  }, [mod, userVersions, activeVersion]);
}

export const isJobLive = (job: Job | null) =>
  !!job && (job.status === "connecting" || job.status === "thinking" || job.status === "writing");
"use client";

import { CATEGORY_BY_KEY, MODEL_BY_ID, categoryNodeId } from "./data";
import { diffStats } from "./engine";
import { fx } from "./fx";
import { CORE_ID, findMod, getGame, isJobLive, useStore, versionsOf, type Job } from "./store";
import type { GenEvent, Mod, ModVersion } from "./types";

let controller: AbortController | null = null;

const patchJob = (fn: (job: Job) => Partial<Job>) =>
  useStore.setState((s) => (s.job ? { job: { ...s.job, ...fn(s.job) } } : {}));

export function cancelForge() {
  controller?.abort();
}

export async function forge(prompt: string, images: string[] = []) {
  const state = useStore.getState();
  if (isJobLive(state.job)) return;

  const text = prompt.trim();
  if (!text) return;
  const model = MODEL_BY_ID[state.model];
  if (state.credits < model.credits) {
    state.toast({ tone: "error", title: "Not enough credits", body: `${model.name} needs ${model.credits} credits. Try Katara for 1.` });
    return;
  }

  const sel = state.selection;
  const refineMod = sel.level === "mod" ? findMod(sel.modId) : undefined;
  const prior = refineMod ? versionsOf(refineMod, state.userVersions) : [];
  const context = refineMod
    ? { gameId: refineMod.gameId, category: refineMod.category, modId: refineMod.id, modName: refineMod.name, version: prior.length + 1 }
    : { gameId: sel.gameId, category: sel.category };

  controller = new AbortController();
  const startedAt = performance.now();
  useStore.setState({
    credits: state.credits - model.credits,
    job: {
      id: "pending",
      status: "connecting",
      prompt: text,
      model: model.id,
      images,
      credits: model.credits,
      refining: !!refineMod,
      version: refineMod ? prior.length + 1 : 1,
      steps: [],
      files: [],
      startedAt: Date.now(),
    },
  });
  fx.setMode("thinking");
  fx.ripple(true);

  // Chunks arrive faster than React needs to paint; batch them per animation frame.
  const pending = new Map<string, string>();
  let raf = 0;
  const flush = () => {
    raf = 0;
    if (!pending.size) return;
    const batch = new Map(pending);
    pending.clear();
    patchJob((job) => ({
      files: job.files.map((f) => (batch.has(f.path) ? { ...f, content: f.content + batch.get(f.path) } : f)),
    }));
  };

  let createdModId: string | null = null;
  let path: string[] = [];
  let rgb = "167 139 250";
  let finished = false;

  const handle = (ev: GenEvent) => {
    switch (ev.type) {
      case "start":
        patchJob(() => ({ id: ev.jobId, status: "thinking" }));
        break;

      case "think":
        patchJob((job) => ({
          steps: [...job.steps.filter((s) => s.id !== ev.id), { id: ev.id, label: ev.label, detail: ev.detail, done: false, startedAt: Date.now() }],
        }));
        fx.ripple();
        if (path.length) fx.packets(path.slice(0, 3), 1, { rgb, speed: 1.4 });
        break;

      case "think-done":
        patchJob((job) => ({ steps: job.steps.map((s) => (s.id === ev.id ? { ...s, done: true, endedAt: Date.now() } : s)) }));
        break;

      case "route": {
        const game = getGame(ev.gameId);
        rgb = game?.rgb ?? rgb;
        path = [CORE_ID, ev.gameId, categoryNodeId(ev.gameId, ev.category), ev.modId];
        patchJob(() => ({ gameId: ev.gameId, category: ev.category, modId: ev.modId, modName: ev.modName }));
        if (!findMod(ev.modId)) {
          const mod: Mod = {
            id: ev.modId,
            gameId: ev.gameId,
            category: ev.category,
            name: ev.modName,
            summary: ev.summary,
            tags: ev.tags,
            createdAt: Date.now(),
            versions: [],
          };
          createdModId = ev.modId;
          useStore.setState((s) => ({ userMods: [...s.userMods, mod] }));
        }
        useStore.getState().select({ level: "mod", gameId: ev.gameId, category: ev.category, modId: ev.modId }, { openPanel: true, focus: "path" });
        useStore.setState({ panelTab: "code" });
        fx.setMode("forging");
        fx.startStream(path, rgb);
        fx.packets(path, 4, { rgb, speed: 1.2, size: 1.4 });
        break;
      }

      case "file":
        patchJob((job) => ({
          status: "writing",
          activeFile: ev.path,
          files: [...job.files, { path: ev.path, language: ev.language, content: "" }],
        }));
        useStore.setState({ activeFile: ev.path });
        break;

      case "chunk":
        pending.set(ev.path, (pending.get(ev.path) ?? "") + ev.text);
        if (!raf) raf = requestAnimationFrame(flush);
        break;

      case "file-done":
        fx.packets(path, 2, { rgb, speed: 1.6 });
        break;

      case "done": {
        cancelAnimationFrame(raf);
        flush();
        finished = true;
        const s = useStore.getState();
        const job = s.job!;
        const mod = findMod(job.modId);
        if (!mod) break;
        const prev = versionsOf(mod, s.userVersions);
        const prevActive = prev.find((v) => v.id === s.activeVersion[mod.id]) ?? prev[prev.length - 1];
        const n = prev.length + 1;
        const { additions, deletions } = diffStats(prevActive?.files, job.files);
        const version: ModVersion = {
          id: `${mod.id}@v${n}-${Date.now().toString(36)}`,
          label: `v${n}`,
          createdAt: Date.now(),
          model: job.model,
          credits: job.credits,
          prompt: job.prompt,
          summary: ev.summary,
          files: job.files,
          additions,
          deletions,
        };
        const seconds = ((performance.now() - startedAt) / 1000).toFixed(1);
        useStore.setState((st) => ({
          userVersions: { ...st.userVersions, [mod.id]: [...(st.userVersions[mod.id] ?? []), version] },
          activeVersion: { ...st.activeVersion, [mod.id]: version.id },
          aiNotes: { ...st.aiNotes, [mod.id]: ev.notes },
          job: st.job ? { ...st.job, status: "done", finishedAt: Date.now() } : null,
        }));
        fx.stopStream();
        fx.setMode("idle");
        fx.burst(mod.id, rgb);
        fx.packets([...path].reverse(), 5, { rgb: "196 181 253", speed: 1.3, gap: 0.12 });
        window.setTimeout(() => fx.ripple(true), 900);
        s.toast({
          tone: "success",
          title: `${mod.name} ${version.label} forged`,
          body: `${job.files.length} files · ${job.credits} credit${job.credits === 1 ? "" : "s"} · ${seconds}s`,
          rgb,
        });
        break;
      }

      case "error":
        throw new Error(ev.message);
    }
  };

  try {
    const res = await fetch("/api/generate", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ prompt: text, model: model.id, images: images.length, context, games: state.customGames }),
      signal: controller.signal,
    });
    if (!res.ok || !res.body) {
      const msg = await res.json().catch(() => ({ error: res.statusText }));
      throw new Error(msg.error ?? "The forge did not respond");
    }
    const reader = res.body.getReader();
    const decoder = new TextDecoder();
    let buffer = "";
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });
      let nl: number;
      while ((nl = buffer.indexOf("\n")) >= 0) {
        const line = buffer.slice(0, nl).trim();
