  } catch (err) {
    cancelAnimationFrame(raf);
    const aborted = controller?.signal.aborted;
    const s = useStore.getState();
    const wroteCode = (s.job?.files.length ?? 0) > 0;
    fx.stopStream();
    fx.setMode("idle");
    useStore.setState((st) => ({
      // Refund when nothing was produced.
      credits: wroteCode ? st.credits : st.credits + (st.job?.credits ?? 0),
      // A brand-new mod that never finished packaging shouldn't linger as an empty node.
      userMods: createdModId ? st.userMods.filter((m) => m.id !== createdModId) : st.userMods,
      job: st.job ? { ...st.job, status: aborted ? "cancelled" : "error", error: aborted ? undefined : String((err as Error).message), finishedAt: Date.now() } : null,
    }));
    if (createdModId) useStore.getState().select({ level: "category", gameId: s.job?.gameId, category: s.job?.category }, { openPanel: false });
