@import "tailwindcss";

@custom-variant dark (&:where(.dark, .dark *));
@custom-variant light (&:where(.light, .light *));

/* ───────────────────────── Theme tokens ───────────────────────── */

:root {
  color-scheme: dark;
  --bg: #05030b;
  --bg-2: #0a0617;
  --bg-3: #140b2b;
  --surface: rgb(15 10 32 / 0.6);
  --surface-2: rgb(22 15 46 / 0.78);
  --surface-3: rgb(40 27 80 / 0.55);
  --surface-soft: rgb(16 11 34 / 0.82);
  --solid: #0e091e;
  --line: rgb(167 139 250 / 0.13);
  --line-2: rgb(167 139 250 / 0.26);
  --ink: #f2eeff;
  --ink-2: #cfc7f0;
  --muted: #958cc0;
  --faint: #5f5789;
  --accent: #a78bfa;
  --accent-ink: #c4b5fd;
  --cyan: #67e8f9;
  --pink: #f0abfc;
  --glow: 167 139 250;
  --panel-shadow: 0 30px 80px -24px rgb(0 0 0 / 0.8), inset 0 1px 0 rgb(255 255 255 / 0.04);
  --code-bg: rgb(7 4 18 / 0.55);
  --tok-k: #c792ea;
  --tok-s: #a8e6a3;
  --tok-n: #f8b26a;
  --tok-c: #6c6497;
  --tok-t: #82d8ff;
  --tok-f: #93b6ff;
  --tok-p: #8f87b8;
  --tok-a: #f0abfc;
  --tok-v: #f5c2e7;
}

:root.light {
  color-scheme: light;
  --bg: #fdfcff;
  --bg-2: #f7f4ff;
  --bg-3: #ede7ff;
  --surface: rgb(255 255 255 / 0.66);
  --surface-2: rgb(255 255 255 / 0.86);
  --surface-3: rgb(243 238 255 / 0.9);
  --surface-soft: rgb(255 255 255 / 0.86);
  --solid: #ffffff;
  --line: rgb(91 33 182 / 0.1);
  --line-2: rgb(91 33 182 / 0.2);
  --ink: #160f2c;
  --ink-2: #3a3162;
  --muted: #6b6390;
  --faint: #a8a1c6;
  --accent: #7c3aed;
  --accent-ink: #6d28d9;
  --cyan: #0891b2;
  --pink: #c026d3;
  --glow: 124 58 237;
  --panel-shadow: 0 24px 60px -28px rgb(76 29 149 / 0.3), inset 0 1px 0 rgb(255 255 255 / 0.9);
  --code-bg: rgb(250 248 255 / 0.8);
  --tok-k: #8a2bc5;
  --tok-s: #23803a;
  --tok-n: #c2410c;
  --tok-c: #9c95bb;
  --tok-t: #0369a1;
  --tok-f: #4338ca;
  --tok-p: #6b6490;
  --tok-a: #be185d;
  --tok-v: #9d174d;
}

@theme inline {
  --color-bg: var(--bg);
  --color-bg-2: var(--bg-2);
  --color-bg-3: var(--bg-3);
  --color-surface: var(--surface);
  --color-surface-2: var(--surface-2);
  --color-surface-3: var(--surface-3);
  --color-solid: var(--solid);
  --color-line: var(--line);
  --color-line-2: var(--line-2);
  --color-ink: var(--ink);
  --color-ink-2: var(--ink-2);
  --color-muted: var(--muted);
  --color-faint: var(--faint);
  --color-accent: var(--accent);
  --color-accent-ink: var(--accent-ink);
  --color-cyan: var(--cyan);
  --color-pink: var(--pink);
  --font-sans: var(--font-inter), ui-sans-serif, system-ui, sans-serif;
  --font-display: var(--font-space), var(--font-inter), ui-sans-serif, sans-serif;
  --font-mono: var(--font-jb), ui-monospace, SFMono-Regular, Menlo, monospace;
  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-spring: cubic-bezier(0.34, 1.56, 0.64, 1);
}

@property --angle {
  syntax: "<angle>";
  initial-value: 0deg;
  inherits: false;
}

html,
body {
  height: 100%;
  background: var(--bg);
  color: var(--ink);
}

body {
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
  font-feature-settings: "ss01", "cv11";
}

::selection {
  background: rgb(var(--glow) / 0.35);
}

* {
  scrollbar-width: thin;
  scrollbar-color: rgb(var(--glow) / 0.28) transparent;
}

/* Theme switch: crossfade everything once instead of per-element transitions. */
.theme-swap,
.theme-swap * {
  transition:
    background-color 0.5s ease,
    border-color 0.5s ease,
    color 0.4s ease,
    fill 0.4s ease,
    box-shadow 0.5s ease !important;
}

/* ───────────────────────── Surfaces ───────────────────────── */

.glass {
  background: linear-gradient(180deg, var(--surface-2), var(--surface));
  backdrop-filter: blur(14px) saturate(140%);
  -webkit-backdrop-filter: blur(14px) saturate(140%);
  border: 1px solid var(--line);
  box-shadow: var(--panel-shadow);
}

/* No backdrop-filter: small chips sit over a canvas that redraws every frame, and
   re-blurring a dozen of them per frame is what made the page stutter. */
.glass-soft {
  background: var(--surface-soft);
  border: 1px solid var(--line);
}

.hairline-top {
  position: relative;
}
.hairline-top::before {
  content: "";
  position: absolute;
  inset: 0 12% auto 12%;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgb(var(--glow) / 0.55), rgb(103 232 249 / 0.45), transparent);
  pointer-events: none;
}
.light .hairline-top::before {
  background: linear-gradient(90deg, transparent, rgb(124 58 237 / 0.35), rgb(8 145 178 / 0.3), transparent);
}

.topbar-logo {
  filter: drop-shadow(0 0 8px rgb(139 92 246 / 0.45));
}
.light .topbar-logo {
  filter: none;
}

.text-glow {
  text-shadow: 0 0 18px rgb(var(--glow) / 0.55);
}
.light .text-glow {
  text-shadow: none;
}

.tint {
  --cc: rgb(var(--c));
  --cc-ink: color-mix(in oklab, rgb(var(--c)) 55%, white);
}
.light .tint {
  --cc: color-mix(in oklab, rgb(var(--c)) 70%, #1b1236);
  --cc-ink: color-mix(in oklab, rgb(var(--c)) 62%, #1b1236);
}

.btn-ghost {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  border-radius: 0.7rem;
  color: var(--ink-2);
  transition:
    background-color 0.2s,
    color 0.2s,
    box-shadow 0.2s,
    transform 0.2s var(--ease-spring);
}
.btn-ghost:hover {
  background: rgb(var(--glow) / 0.1);
  color: var(--ink);
}
.btn-ghost:active {
  transform: scale(0.94);
}

.kbd {
  font-family: var(--font-jb), monospace;
  font-size: 10px;
  line-height: 1;
  padding: 3px 5px;
  border-radius: 5px;
  border: 1px solid var(--line-2);
  color: var(--muted);
  background: rgb(var(--glow) / 0.06);
}

.shimmer-text {
  background: linear-gradient(
    100deg,
    var(--ink-2) 0%,
    var(--ink-2) 35%,
    #fff 46%,
    var(--cyan) 52%,
    var(--ink-2) 64%,
    var(--ink-2) 100%
  );
  background-size: 250% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: shimmer 2.2s linear infinite;
}
.light .shimmer-text {
  background-image: linear-gradient(
    100deg,
    var(--ink-2) 0%,
    var(--ink-2) 35%,
    var(--accent) 46%,
    var(--cyan) 52%,
    var(--ink-2) 64%,
    var(--ink-2) 100%
  );
}

/* ───────────────────────── Prompt dock ───────────────────────── */

.prompt-shell {
  position: relative;
  border-radius: 24px;
  --spin-speed: 9s;
}
.prompt-shell::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: conic-gradient(
    from var(--angle),
    rgb(var(--glow) / 0.18) 0%,
    rgb(103 232 249 / 0.75) 12%,
    rgb(var(--glow) / 0.18) 26%,
    rgb(var(--glow) / 0.18) 48%,
    rgb(240 171 252 / 0.7) 62%,
    rgb(var(--glow) / 0.18) 76%
  );
  -webkit-mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  mask-composite: exclude;
  pointer-events: none;
  z-index: 2;
}
.prompt-shell[data-active="true"]::before,
.prompt-shell[data-busy="true"]::before {
  animation: border-spin var(--spin-speed) linear infinite;
}
.prompt-shell::after {
  content: "";
  position: absolute;
  inset: -1px;
  border-radius: inherit;
  background: linear-gradient(90deg, rgb(103 232 249 / 0.45), rgb(167 139 250 / 0.35) 50%, rgb(240 171 252 / 0.45));
  filter: blur(18px);
  opacity: 0.2;
  z-index: -1;
  transition: opacity 0.5s;
  pointer-events: none;
}
.prompt-shell[data-active="true"] {
  --spin-speed: 6s;
}
.prompt-shell[data-active="true"]::after {
  opacity: 0.32;
}
.prompt-shell[data-busy="true"] {
  --spin-speed: 1.3s;
}
.prompt-shell[data-busy="true"]::after {
  opacity: 0.85;
}
.light .prompt-shell::after {
  opacity: 0.18;
}
.light .prompt-shell[data-active="true"]::after {
  opacity: 0.35;
}

.prompt-textarea::placeholder {
  color: var(--faint);
}

.mic-live {
  background: linear-gradient(135deg, #f43f5e, #d946ef);
  color: #fff;
  box-shadow:
    0 0 0 0 rgb(244 63 94 / 0.6),
    0 0 22px rgb(244 63 94 / 0.55);
  animation: mic-ring 1.4s ease-out infinite;
}
.mic-bars span {
  display: block;
  width: 2.5px;
  border-radius: 2px;
  background: currentColor;
  animation: mic-bar 0.9s ease-in-out infinite;
}

/* A game's real logo standing in for its emblem (GameEmblem). White artwork is inked on light. */
.game-logo {
  display: inline-block;
  width: 1.25em;
  height: 1.25em;
  object-fit: contain;
  vertical-align: middle;
  user-select: none;
}
.light .game-logo[data-tone="light"] {
  filter: brightness(0.16);
}

/* Badge holding the brain in the prompt dock's thinking trace. */
.think-badge {
  display: grid;
  place-items: center;
  flex-shrink: 0;
  width: 38px;
  height: 38px;
  border-radius: 12px;
  font-size: 27px;
  background: radial-gradient(circle at 50% 45%, rgb(var(--glow) / 0.22), rgb(var(--glow) / 0.07) 70%);
  box-shadow: inset 0 0 0 1px rgb(var(--glow) / 0.22), 0 0 18px -4px rgb(var(--glow) / 0.55);
}
.light .think-badge {
  box-shadow: inset 0 0 0 1px rgb(var(--glow) / 0.2);
}

/* The circuit brain (ThinkingBrain.tsx): brand gradient, deeper on the light theme. While it
   thinks, signals fire out along the traces in a clockwise sweep (one round = 1.6s; each signal
   crosses in 30% of that) and light the nodes they reach, while the chip's core pulses. */
.brain {
  --brain-spark: #a5f3fc;
}
.light .brain {
  --brain-spark: #0891b2;
}
.brain-stop-1 { stop-color: #22d3ee; }
.brain-stop-2 { stop-color: #4f7cff; }
.brain-stop-3 { stop-color: #9b5cf6; }
.brain-stop-4 { stop-color: #e83fd0; }
.light .brain-stop-1 { stop-color: #0891b2; }
.light .brain-stop-2 { stop-color: #2563eb; }
.light .brain-stop-3 { stop-color: #7c3aed; }
.light .brain-stop-4 { stop-color: #c026d3; }
.brain.is-thinking .brain-trace {
  stroke-opacity: 0.55;
}
.brain.is-thinking .brain-core {
  animation: brain-core 0.8s ease-in-out infinite alternate;
}
.brain.is-thinking .brain-node {
  fill: var(--brain-spark);
  fill-opacity: 0;
  animation: brain-node 1.6s ease-out infinite;
}
.brain-signal {
  stroke: var(--brain-spark);
  stroke-width: 1.5;
  stroke-dasharray: 0.45 1.5;
  stroke-dashoffset: 0.45;
  filter: drop-shadow(0 0 1px var(--brain-spark));
  animation: brain-signal 1.6s cubic-bezier(0.4, 0, 0.6, 1) infinite;
}
.light .brain-signal {
  filter: none;
}

/* ───────────────────────── Code view ───────────────────────── */

.code {
  font-family: var(--font-jb), ui-monospace, monospace;
  font-size: 12.5px;
  line-height: 1.7;
  tab-size: 4;
  font-variant-ligatures: contextual;
}
.code .ln {
  color: var(--faint);
  user-select: none;
}
.code .line-new {
  animation: line-in 0.7s ease-out;
}
.tok-k { color: var(--tok-k); }
.tok-s { color: var(--tok-s); }
.tok-n { color: var(--tok-n); }
.tok-c { color: var(--tok-c); font-style: italic; }
.tok-t { color: var(--tok-t); }
.tok-f { color: var(--tok-f); }
.tok-p { color: var(--tok-p); }
.tok-a { color: var(--tok-a); }
.tok-v { color: var(--tok-v); }

.caret {
  display: inline-block;
  width: 7px;
  height: 1.15em;
  margin-left: 1px;
  vertical-align: -0.2em;
  border-radius: 1px;
  background: var(--cyan);
  box-shadow: 0 0 10px var(--cyan);
  animation: caret 0.9s steps(1) infinite;
}

.write-head {
  background: linear-gradient(90deg, rgb(103 232 249 / 0.12), rgb(167 139 250 / 0.06) 60%, transparent);
}
.light .write-head {
  background: linear-gradient(90deg, rgb(8 145 178 / 0.1), rgb(124 58 237 / 0.04) 60%, transparent);
}

.md h1, .md h2, .md h3 {
  font-family: var(--font-space), sans-serif;
  color: var(--ink);
  font-weight: 600;
}
.md h1 { font-size: 1.05rem; margin: 0.2rem 0 0.6rem; }
.md h2 { font-size: 0.92rem; margin: 1rem 0 0.4rem; }
.md h3 { font-size: 0.85rem; margin: 0.8rem 0 0.3rem; }
.md p { margin: 0.35rem 0; color: var(--ink-2); }
.md ul, .md ol { margin: 0.3rem 0 0.5rem; padding-left: 1.1rem; color: var(--ink-2); }
.md ul { list-style: none; padding-left: 0.2rem; }
.md ul li { position: relative; padding-left: 1rem; margin: 0.22rem 0; }
.md ul li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.62em;
  width: 5px;
  height: 5px;
  border-radius: 2px;
  transform: rotate(45deg);
  background: var(--accent);
  box-shadow: 0 0 8px var(--accent);
}
.md ol { list-style: decimal; }
.md ol li { margin: 0.22rem 0; }
.md code {
  font-family: var(--font-jb), monospace;
