  border-radius: 10px;
  background: var(--code-bg);
  border: 1px solid var(--line);
  overflow-x: auto;
  margin: 0.5rem 0;
  color: var(--ink-2);
}
.md strong { color: var(--ink); font-weight: 600; }

/* ───────────────────────── Keyframes ───────────────────────── */

@keyframes spin {
  to { transform: rotate(360deg); }
}
@keyframes border-spin {
  to { --angle: 360deg; }
}
@keyframes shimmer {
  0% { background-position: 120% 0; }
  100% { background-position: -120% 0; }
}
@keyframes ripple {
  0% { transform: scale(0.85); opacity: 0.9; }
  100% { transform: scale(2.6); opacity: 0; }
}
@keyframes node-hit {
  0% { transform: scale(1); }
  30% { transform: scale(1.32); filter: brightness(1.8); }
  100% { transform: scale(1); }
}
@keyframes forge-pulse {
  0%, 100% { transform: scale(1); filter: brightness(1); }
  50% { transform: scale(1.5); filter: brightness(1.7); }
}
@keyframes materialize {
  0% { opacity: 0; filter: blur(8px) brightness(3); }
  40% { opacity: 1; }
  100% { opacity: 1; filter: blur(0) brightness(1); }
}
@keyframes caret {
  0%, 49% { opacity: 1; }
  50%, 100% { opacity: 0; }
}
@keyframes line-in {
  0% { background: rgb(103 232 249 / 0.14); }
  100% { background: transparent; }
}
@keyframes mic-ring {
  0% { box-shadow: 0 0 0 0 rgb(244 63 94 / 0.55), 0 0 22px rgb(244 63 94 / 0.5); }
  100% { box-shadow: 0 0 0 14px rgb(244 63 94 / 0), 0 0 22px rgb(244 63 94 / 0.5); }
}
@keyframes mic-bar {
  0%, 100% { height: 4px; }
  50% { height: 14px; }
}
@keyframes brain-core {
  from { fill-opacity: 0.12; }
  to { fill-opacity: 0.8; }
}
@keyframes brain-node {
  0%, 22% { fill-opacity: 0; }
  32% { fill-opacity: 1; }
  70%, 100% { fill-opacity: 0; }
}
@keyframes brain-signal {
  0% { stroke-dashoffset: 0.45; }
  30%, 100% { stroke-dashoffset: -1; }
}
@keyframes rise-in {
  from { opacity: 0; transform: translateY(10px) scale(0.98); filter: blur(4px); }
  to { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); }
}
@keyframes fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}
@keyframes slide-in-right {
  from { opacity: 0; transform: translateX(28px); }
  to { opacity: 1; transform: translateX(0); }
}
@keyframes pop-in {
  from { opacity: 0; transform: translateY(6px) scale(0.96); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes progress-sheen {
  from { transform: translateX(-100%); }
  to { transform: translateX(250%); }
}
@keyframes orbit-dot {
  from { transform: rotate(0deg) translateX(7px) rotate(0deg); }
  to { transform: rotate(360deg) translateX(7px) rotate(-360deg); }
}

.animate-rise { animation: rise-in 0.55s var(--ease-out-expo) both; }
.animate-fade { animation: fade-in 0.4s ease both; }
.animate-slide-right { animation: slide-in-right 0.5s var(--ease-out-expo) both; }
.animate-pop { animation: pop-in 0.28s var(--ease-out-expo) both; }

@media (prefers-reduced-motion: reduce) {
  .core-sparks .spark,
  .brain * {
    animation: none !important;
  }
  .brain-signal {
    display: none;
  }
}

