function files(dir: string): string[] {
  return readdirSync(dir).flatMap((n) => { const p = join(dir, n); return statSync(p).isDirectory() ? files(p) : [p]; });
}
describe("cyrus is behind the mod builder preview gate", () => {
  it("both pages render through the gated loader", () => {
    for (const f of files("app/dashboard/cyrus").filter((f) => f.endsWith("page.tsx"))) assert.match(readFileSync(f, "utf8"), /CyrusPage\(/, f);
    assert.match(readFileSync("app/dashboard/cyrus/shared.tsx", "utf8"), /await requireModBuilderUser\(\)/);
  });
  it("the static nav never lists it", () => {
    assert.doesNotMatch(readFileSync("lib/nx/nav.ts", "utf8"), /cyrus/i);
  });
  it("new API routes resolve the preview user", () => {
    for (const f of ["app/api/mod-builder/uploads/route.ts", "app/api/mod-builder/projects/[id]/route.ts", "app/api/mod-builder/builds/[id]/attachments/[n]/route.ts", "app/api/mod-builder/builds/[id]/live/route.ts"]) {
      assert.match(readFileSync(f, "utf8"), /ownedBuild\(|modBuilderUser\(\)/, f);
    }
  });
  it("customer copy never names the underlying models", () => {
    for (const f of files("components/cyrus")) assert.doesNotMatch(readFileSync(f, "utf8"), /\b(Haiku|Sonnet|Opus|Claude|Anthropic)\b/, f);
  });
});

describe("cyrus web (core -> game -> category -> mod)", () => {
  const many = Array.from({ length: 11 }, (_, i) => view(`r${i}`, { createdAt: `2026-10-0${(i % 7) + 1}T00:00:00.000Z` }));
  it("every game in the registry is a branch of the core; only live games carry categories", () => {
    const t = buildTree(groupProjects(many), CYRUS_TEMPLATES);
    const games = t.nodes.filter((n) => n.kind === "game");
    assert.equal(games.length, CYRUS_GAMES.length);
    for (const g of games) assert.equal(g.parent, "core");
    for (const c of t.nodes.filter((n) => n.kind === "cat")) assert.equal(t.byId.get(c.parent!)!.soon, undefined, "categories hang off a live game");
    assert.ok(t.nodes.some((n) => n.kind === "add"));
  });
  it("every mod hangs off a category; at most 3 per category plus a +N more chip", () => {
    const ps = groupProjects(many);
    const t = buildTree(ps, CYRUS_TEMPLATES);
    const mods = t.nodes.filter((n) => n.kind === "mod");
    for (const m of mods) assert.equal(t.byId.get(m.parent!)!.kind, "cat");
    const more = t.nodes.filter((n) => n.kind === "more").reduce((s, n) => s + Number(n.label.match(/\d+/)![0]), 0);
    assert.equal(mods.length + more, ps.length, "every project is on the web or counted in +N more");
    const perCat = new Map<string, number>();
    for (const m of mods) perCat.set(m.parent!, (perCat.get(m.parent!) ?? 0) + 1);
    for (const n of perCat.values()) assert.ok(n <= 3);
  });
  it("the selected mod is always shown, and its path runs core -> game -> category -> mod", () => {
    const ps = groupProjects(many);
    const last = ps[ps.length - 1];
    const t = buildTree(ps, CYRUS_TEMPLATES, { selectedRoot: last.rootId });
    const path = pathTo(t, `m:${last.rootId}`);
    assert.deepEqual(path.map((id) => t.byId.get(id)!.kind), ["core", "game", "cat", "mod"]);
  });
  it("empty categories show templates (marked) and a start chip", () => {
    const t = buildTree([], CYRUS_TEMPLATES);
    assert.ok(t.nodes.some((n) => n.kind === "tpl"));
    assert.equal(t.nodes.filter((n) => n.kind === "start").length, t.nodes.filter((n) => n.kind === "cat").length);
  });
  it("mods are classified deterministically with an Other fallback", () => {
    assert.equal(classifyMod({ title: "Coin Shop", text: "A shop where players spend coins" }), "gameplay");
    assert.equal(classifyMod({ title: "Spawn & homes", text: "/spawn and /home commands" }), "utility");
    assert.equal(classifyMod({ title: "Village Overhaul", text: "new villages and structures" }), "structures");
    assert.equal(classifyMod({ title: "Zzz", text: "qqq" }), "other");
    const [p] = groupProjects([view("cx")]);
    assert.equal(projectCategory(p), projectCategory(p));
  });
  it("real build events map to light on the web", () => {
    assert.deepEqual(eventAction("Reading 1.png", "planning"), { kind: "inward", file: "1.png" });
    assert.deepEqual(eventAction("Wrote ShopMenu.java", "coding"), { kind: "ripple", file: "ShopMenu.java" });
    assert.deepEqual(eventAction("Compiling against Paper 1.21.11", "compiling"), { kind: "gather" });
    assert.deepEqual(eventAction("Compiler found 2 errors. Fixing it automatically (fix 1 of 3)", "repairing"), { kind: "warn" });
    assert.deepEqual(eventAction("Running the safety check", "scanning"), { kind: "scan" });
    assert.deepEqual(eventAction("Ready: Heal-1.0.0.jar", "succeeded"), { kind: "bloom" });
    assert.equal(eventAction("Error details", "repairing"), null);
