// One source file as text, proxied from the build service (the source lives there).
export async function GET(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const o = await ownedBuild((await params).id);
  if (!o) return NOT_FOUND();
  const path = new URL(req.url).searchParams.get("path") || "";
  if (!/^[A-Za-z0-9_./-]{1,300}$/.test(path) || path.includes("..")) return NextResponse.json({ error: "Bad path" }, { status: 400 });
  try {
    const r = await svcSource(await serviceBuildId(o.build.id), path); // fork copies read the original's source
    if (!r.ok) return NextResponse.json({ error: "File not found" }, { status: 404 });
    // Finished builds never change; an in-flight one may (Cyrus polls it while building).
    const cache = isTerminal(o.build.status) ? "private, max-age=300" : "no-store";
    return new Response(await r.text(), { headers: { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": cache, "X-Content-Type-Options": "nosniff" } });
  } catch {
    return NextResponse.json({ error: "The builder is offline right now." }, { status: 503 });
  }
}
