"use client";

import { useCallback, useEffect, useLayoutEffect, useRef, useState, type ClipboardEvent, type DragEvent } from "react";
import { CategoryIcon } from "@/components/icons/CategoryIcons";
import { GameEmblem } from "@/components/icons/GameEmblems";
import { BoltIcon, CloseIcon, ImageIcon, SendIcon, SparkleIcon, StopIcon } from "@/components/icons/ui";
import { CATEGORY_BY_KEY, MODEL_BY_ID } from "@/lib/data";
import { cancelForge, forge } from "@/lib/forge";
import { fx } from "@/lib/fx";
import { useMediaQuery } from "@/lib/hooks";
import { isJobLive, useGame, useMod, useModVersions, useStore } from "@/lib/store";
import { ModelSelect } from "./ModelSelect";
import { StarterIdeas, type StarterIdea } from "./StarterIdeas";
import { ThinkingTrace } from "./ThinkingTrace";
import { VoiceButton } from "./VoiceButton";

interface Attachment {
  id: string;
  url: string;
  name: string;
}

export function PromptDock() {
  const [text, setText] = useState("");
  const [images, setImages] = useState<Attachment[]>([]);
  const [focused, setFocused] = useState(false);
  const [typing, setTyping] = useState(false);
  const [dragOver, setDragOver] = useState(false);
  const taRef = useRef<HTMLTextAreaElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const typingTimer = useRef(0);
  const typeInTimer = useRef(0);
  const voiceBase = useRef("");

  const job = useStore((s) => s.job);
  const live = isJobLive(job);
  const selection = useStore((s) => s.selection);
  const model = MODEL_BY_ID[useStore((s) => s.model)];
  const credits = useStore((s) => s.credits);
  const select = useStore((s) => s.select);
  const promptFocusTick = useStore((s) => s.promptFocusTick);
  const panelOpen = useStore((s) => s.panelOpen);
  const mod = useMod(selection.level === "mod" ? selection.modId : undefined);
  const { versions } = useModVersions(mod);

  useEffect(() => {
    if (promptFocusTick) taRef.current?.focus();
  }, [promptFocusTick]);

  // Auto-grow the textarea.
  useLayoutEffect(() => {
    const ta = taRef.current;
    if (!ta) return;
    ta.style.height = "0px";
    ta.style.height = `${Math.min(ta.scrollHeight, 180)}px`;
  }, [text]);

  const pulseTyping = useCallback(() => {
    setTyping(true);
    window.clearTimeout(typingTimer.current);
    typingTimer.current = window.setTimeout(() => setTyping(false), 1100);
  }, []);

  const addFiles = useCallback((files: File[]) => {
    const imgs = files.filter((f) => f.type.startsWith("image/")).slice(0, 6);
    if (!imgs.length) return;
    setImages((prev) =>
      [...prev, ...imgs.map((f) => ({ id: Math.random().toString(36).slice(2), url: URL.createObjectURL(f), name: f.name || "pasted image" }))].slice(0, 6),
    );
    fx.keystroke(1.5);
  }, []);

  const onPaste = (e: ClipboardEvent<HTMLTextAreaElement>) => {
    const files = Array.from(e.clipboardData.items)
      .filter((i) => i.kind === "file" && i.type.startsWith("image/"))
      .map((i) => i.getAsFile())
      .filter((f): f is File => !!f);
    if (files.length) {
      e.preventDefault();
      addFiles(files);
    }
  };

  const onDrop = (e: DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    addFiles(Array.from(e.dataTransfer.files));
  };

  const removeImage = (id: string) =>
    setImages((prev) => {
      const hit = prev.find((i) => i.id === id);
      if (hit) URL.revokeObjectURL(hit.url);
      return prev.filter((i) => i.id !== id);
    });

  const submit = () => {
    if (live || !text.trim()) return;
    window.clearInterval(typeInTimer.current);
    forge(text, images.map((i) => i.url));
    setText("");
    setImages([]);
  };

  // Starter ideas type themselves in — which also charges the core.
  const pickIdea = (idea: StarterIdea) => {
    if (live) return;
    window.clearInterval(typeInTimer.current);
    select({ level: "category", gameId: idea.gameId, category: idea.category });
    let i = 0;
    setText("");
    typeInTimer.current = window.setInterval(() => {
      i = Math.min(idea.prompt.length, i + 2 + Math.floor(Math.random() * 2));
      setText(idea.prompt.slice(0, i));
      fx.keystroke(0.3);
      pulseTyping();
      if (i >= idea.prompt.length) {
        window.clearInterval(typeInTimer.current);
        taRef.current?.focus();
      }
    }, 22);
  };

  useEffect(() => () => window.clearInterval(typeInTimer.current), []);

  // Context: where in the network this prompt will land.
  const game = useGame(selection.gameId);
  const cat = selection.category ? CATEGORY_BY_KEY[selection.category] : undefined;
  const placeholder =
    selection.level === "mod" && mod
      ? `Refine ${mod.name} — e.g. "add a charged special attack"`
      : cat && game
        ? `Describe a ${game.short} ${cat.label.toLowerCase().replace(/s$/, "")} mod…`
        : game
          ? `Describe a ${game.name} mod…`
          : "Describe a mod — Cyrus routes it to the right game and category…";

  const canAfford = credits >= model.credits;
  const sendable = !!text.trim() && !live && canAfford;
  const wide = useMediaQuery("(min-width: 1024px)");
  const dockStyle =
    panelOpen && wide
      ? { left: "calc((100vw - min(560px, 40vw)) / 2)" }
      : undefined;

  return (
    <div
      className="fixed bottom-4 left-1/2 z-30 w-[min(780px,calc(100vw-24px))] -translate-x-1/2 transition-[left] duration-500 ease-[var(--ease-out-expo)] md:bottom-6"
      style={dockStyle}
    >
      <ThinkingTrace />

      <div
        className="prompt-shell"
        data-active={focused || typing ? "true" : "false"}
        data-busy={live ? "true" : "false"}
        onDragOver={(e) => {
          if (Array.from(e.dataTransfer.types).includes("Files")) {
            e.preventDefault();
            setDragOver(true);
          }
        }}
        onDragLeave={() => setDragOver(false)}
        onDrop={onDrop}
      >
        <div className="glass relative rounded-[24px] !border-transparent">
          {dragOver && (
            <div className="absolute inset-1.5 z-10 grid place-items-center rounded-[20px] border border-dashed border-accent/60 bg-[rgb(var(--glow)/0.1)] text-[13px] font-medium text-accent-ink backdrop-blur-sm">
              Drop images to give Cyrus a reference
            </div>
          )}

          {/* Context chip */}
          <div className="flex items-center gap-2 px-4 pt-3">
            {selection.level === "core" ? (
              <span className="inline-flex items-center gap-1.5 rounded-full bg-[rgb(var(--glow)/0.1)] px-2.5 py-1 text-[11px] font-medium text-accent-ink">
                <SparkleIcon /> Auto-route through the core
              </span>
            ) : (
              <span
                className="tint inline-flex max-w-full items-center gap-1.5 truncate rounded-full py-1 pl-1.5 pr-1 text-[11px] font-medium text-ink-2"
                style={{ ["--c" as string]: (cat ?? game)!.rgb, background: `rgb(${(cat ?? game)!.rgb} / 0.12)` }}
              >
                <span className="text-[13px]" style={{ color: "var(--cc)" }}>
                  {cat ? <CategoryIcon k={cat.key} /> : game && <GameEmblem emblem={game.emblem} logo={game.logo} logoTone={game.logoTone} />}
                </span>
                {selection.level === "mod" && mod ? (
                  <span className="truncate">
                    Refining <b className="font-semibold text-ink">{mod.name}</b> → v{versions.length + 1}
                  </span>
                ) : (
                  <span className="truncate">
                    {game?.short}
                    {cat && <> › {cat.label}</>}
                  </span>
                )}
                <button
                  type="button"
                  aria-label="Clear context"
                  onClick={() => select({ level: "core" })}
                  className="ml-0.5 grid h-4 w-4 place-items-center rounded-full text-[9px] text-muted hover:bg-[rgb(var(--glow)/0.15)] hover:text-ink"
                >
                  <CloseIcon />
                </button>
              </span>
            )}
          </div>

          {/* Pasted images */}
          {images.length > 0 && (
            <div className="flex gap-2 overflow-x-auto px-4 pt-2.5">
              {images.map((img) => (
                <div key={img.id} className="animate-pop group relative h-16 w-16 shrink-0 overflow-hidden rounded-xl border border-line-2">
                  {/* eslint-disable-next-line @next/next/no-img-element */}
                  <img src={img.url} alt={img.name} className="h-full w-full object-cover" />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/40 to-transparent" />
                  <button
                    type="button"
                    aria-label={`Remove ${img.name}`}
                    onClick={() => removeImage(img.id)}
                    className="absolute right-1 top-1 grid h-5 w-5 place-items-center rounded-full bg-black/60 text-[10px] text-white opacity-0 transition group-hover:opacity-100"
                  >
                    <CloseIcon />
                  </button>
                </div>
              ))}
            </div>
          )}

          <textarea
            ref={taRef}
            rows={1}
            value={text}
            disabled={live}
            placeholder={live ? "Cyrus is forging… you can watch the beams travel the branch." : placeholder}
            onChange={(e) => {
              setText(e.target.value);
              fx.keystroke();
              pulseTyping();
            }}
            onKeyDown={(e) => {
              if (e.key === "Enter" && !e.shiftKey && !e.nativeEvent.isComposing) {
                e.preventDefault();
                submit();
              }
            }}
            onPaste={onPaste}
            onFocus={() => setFocused(true)}
            onBlur={() => setFocused(false)}
            className="prompt-textarea block max-h-[180px] w-full resize-none bg-transparent px-4 pb-2 pt-2.5 text-[15px] leading-relaxed text-ink outline-none disabled:opacity-60"
            aria-label="Describe your mod"
          />

          {/* Toolbar */}
          <div className="flex items-center gap-1.5 px-2.5 pb-2.5">
            <ModelSelect disabled={live} />
            <input
              ref={fileRef}
              type="file"
              accept="image/*"
              multiple
              hidden
              onChange={(e) => {
                addFiles(Array.from(e.target.files ?? []));
                e.target.value = "";
              }}
            />
            <button
              type="button"
              onClick={() => fileRef.current?.click()}
              disabled={live}
              className="btn-ghost h-9 w-9 text-[17px] disabled:opacity-40"
              title="Attach reference images (or paste them)"
              aria-label="Attach images"
            >
              <ImageIcon />
            </button>
            <span className="ml-1 hidden text-[11px] text-faint sm:inline">
              <span className="kbd">Enter</span> to forge · <span className="kbd">Shift</span>+<span className="kbd">Enter</span> newline
            </span>

            <div className="ml-auto flex items-center gap-1.5">
              <span
                className={`hidden items-center gap-1 rounded-lg px-2 py-1 text-[11px] font-medium sm:inline-flex ${canAfford ? "text-muted" : "text-rose-400"}`}
                title={`${model.name} costs ${model.credits} credit${model.credits === 1 ? "" : "s"}`}
              >
                <BoltIcon className="text-[12px]" />
                {model.credits}
              </span>
              <VoiceButton
                disabled={live}
                onStart={() => {
                  voiceBase.current = text;
                }}
                onTranscript={(t) => {
                  const base = voiceBase.current;
                  setText(base ? `${base.trimEnd()} ${t}` : t);
                  pulseTyping();
                }}
              />
              {live ? (
                <button
                  type="button"
                  onClick={cancelForge}
                  className="grid h-9 w-9 place-items-center rounded-xl bg-[rgb(var(--glow)/0.14)] text-[15px] text-ink transition hover:bg-rose-500/20 hover:text-rose-400"
                  aria-label="Stop forging"
                  title="Stop"
                >
                  <StopIcon />
                </button>
              ) : (
                <button
                  type="button"
                  onClick={submit}
                  disabled={!sendable}
                  aria-label="Forge mod"
                  title={canAfford ? "Forge" : "Not enough credits"}
                  className="group relative grid h-9 w-9 place-items-center overflow-hidden rounded-xl text-[16px] text-white transition enabled:hover:scale-105 enabled:active:scale-95 disabled:opacity-35"
                  style={{
                    background: "linear-gradient(135deg, #8b5cf6, #6366f1 45%, #06b6d4)",
                    boxShadow: sendable ? "0 0 22px rgb(139 92 246 / 0.6), inset 0 1px 0 rgb(255 255 255 / 0.3)" : undefined,
                  }}
                >
                  <span className="absolute inset-0 -translate-x-full bg-gradient-to-r from-transparent via-white/40 to-transparent transition duration-700 group-enabled:group-hover:translate-x-full" />
                  <SendIcon className="relative" />
                </button>
              )}
            </div>
          </div>
        </div>
      </div>

      {!live && !text && <StarterIdeas onPick={pickIdea} />}
    </div>
  );
}
