export function ModelSelect({ disabled }: { disabled?: boolean }) {
  const model = useStore((s) => s.model);
  const setModel = useStore((s) => s.setModel);
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  const current = MODEL_BY_ID[model];

  useEffect(() => {
    if (!open) return;
    const close = (e: PointerEvent) => {
      if (!ref.current?.contains(e.target as Node)) setOpen(false);
    };
    const esc = (e: KeyboardEvent) => e.key === "Escape" && setOpen(false);
    window.addEventListener("pointerdown", close);
    window.addEventListener("keydown", esc);
    return () => {
      window.removeEventListener("pointerdown", close);
      window.removeEventListener("keydown", esc);
    };
  }, [open]);

  return (
    <div ref={ref} className="relative">
      <button
        type="button"
        disabled={disabled}
        onClick={() => setOpen((o) => !o)}
        aria-haspopup="listbox"
        aria-expanded={open}
        className="tint group flex h-9 items-center gap-2 rounded-xl border border-line bg-[rgb(var(--glow)/0.06)] pl-2 pr-2.5 text-[13px] font-medium text-ink transition hover:border-line-2 hover:bg-[rgb(var(--glow)/0.12)] disabled:opacity-50"
        style={{ ["--c" as string]: current.rgb }}
      >
        <span className="grid h-6 w-6 place-items-center rounded-lg text-[15px]" style={{ color: "var(--cc)", background: `rgb(${current.rgb} / 0.14)` }}>
          <ModelGlyph id={current.id} />
        </span>
        <span className="font-display">{current.name}</span>
        <CreditMeter tier={MODELS.indexOf(current) + 1} rgb={current.rgb} />
        <ChevronDownIcon className={`text-muted transition ${open ? "rotate-180" : ""}`} />
      </button>

      {open && (
        <div role="listbox" className="glass animate-pop absolute bottom-[calc(100%+10px)] left-0 z-50 w-[320px] rounded-2xl p-1.5">
          <div className="px-3 pb-1.5 pt-2 text-[10px] font-semibold uppercase tracking-[0.18em] text-muted">Forge model</div>
          {MODELS.map((m, i) => {
            const active = m.id === model;
            return (
              <button
                key={m.id}
                role="option"
                aria-selected={active}
                type="button"
                onClick={() => {
                  setModel(m.id);
                  setOpen(false);
                }}
                className={`tint flex w-full items-start gap-3 rounded-xl px-3 py-2.5 text-left transition hover:bg-[rgb(var(--glow)/0.09)] ${active ? "bg-[rgb(var(--glow)/0.1)]" : ""}`}
                style={{ ["--c" as string]: m.rgb }}
              >
                <span
                  className="mt-0.5 grid h-9 w-9 shrink-0 place-items-center rounded-xl text-[19px]"
                  style={{ color: "var(--cc)", background: `rgb(${m.rgb} / 0.13)`, boxShadow: `inset 0 0 0 1px rgb(${m.rgb} / 0.35)` }}
                >
                  <ModelGlyph id={m.id} />
                </span>
                <span className="min-w-0 flex-1">
                  <span className="flex items-center gap-2">
                    <span className="font-display text-[14px] font-semibold text-ink">{m.name}</span>
                    <span className="text-[11px] text-muted">{m.tagline}</span>
                    {active && <CheckIcon className="ml-auto text-accent" />}
                  </span>
                  <span className="mt-0.5 block text-[12px] leading-snug text-ink-2">{m.description}</span>
                  <span className="mt-1.5 flex items-center gap-2 text-[11px] text-muted">
                    <CreditMeter tier={i + 1} rgb={m.rgb} />
                    <span className="inline-flex items-center gap-1">
                      <BoltIcon className="text-[11px]" style={{ color: "var(--cc)" }} />
                      {m.credits} credit{m.credits === 1 ? "" : "s"} / forge
                    </span>
                  </span>
                </span>
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState, type ReactNode } from "react";
import { CategoryIcon } from "@/components/icons/CategoryIcons";
