    <aside
      className="glass animate-slide-right fixed inset-x-2 bottom-2 top-[68px] z-40 flex flex-col overflow-hidden rounded-[22px] lg:inset-x-auto lg:bottom-5 lg:right-5 lg:top-[76px] lg:w-[min(540px,calc(40vw-20px))]"
