interface Dir {
  name: string;
  path: string;
  dirs: Map<string, Dir>;
  files: ModFile[];
}

function buildTree(files: ModFile[]): Dir {
  const root: Dir = { name: "", path: "", dirs: new Map(), files: [] };
  for (const f of files) {
    const parts = f.path.split("/");
    let cur = root;
    for (let i = 0; i < parts.length - 1; i++) {
      const p = parts.slice(0, i + 1).join("/");
      if (!cur.dirs.has(parts[i])) cur.dirs.set(parts[i], { name: parts[i], path: p, dirs: new Map(), files: [] });
      cur = cur.dirs.get(parts[i])!;
    }
    cur.files.push(f);
  }
  // Collapse single-child folder chains (src/main/java/dev → one row), like an IDE.
  const compact = (d: Dir): Dir => {
    for (const [k, child] of d.dirs) {
      let c = child;
      while (c.files.length === 0 && c.dirs.size === 1) {
        const only = [...c.dirs.values()][0];
        c = { ...only, name: `${c.name}/${only.name}` };
      }
      d.dirs.set(k, compact(c));
    }
    return d;
  };
  return compact(root);
}

function DirView({
  dir,
  depth,
  active,
  writing,
  collapsed,
  toggle,
  onOpen,
}: {
  dir: Dir;
  depth: number;
  active?: string;
  writing?: string;
  collapsed: Set<string>;
  toggle: (p: string) => void;
  onOpen: (path: string) => void;
}) {
  return (
    <>
      {[...dir.dirs.values()].map((d) => {
        const closed = collapsed.has(d.path);
        return (
          <div key={d.path}>
            <button
              type="button"
              onClick={() => toggle(d.path)}
              className="flex w-full items-center gap-1.5 rounded-lg py-1.5 pr-2 text-left text-[12.5px] text-ink-2 transition hover:bg-[rgb(var(--glow)/0.07)]"
              style={{ paddingLeft: 8 + depth * 16 }}
            >
              <ChevronRightIcon className={`text-[11px] text-faint transition ${closed ? "" : "rotate-90"}`} />
              <FolderIcon className="text-accent" />
              <span className="truncate font-mono text-[12px]">{d.name}</span>
            </button>
            {!closed && (
              <div className="relative">
                <span className="absolute bottom-1 top-0 w-px bg-line" style={{ left: 15 + depth * 16 }} />
                <DirView dir={d} depth={depth + 1} active={active} writing={writing} collapsed={collapsed} toggle={toggle} onOpen={onOpen} />
              </div>
            )}
          </div>
        );
      })}
      {dir.files.map((f) => {
        const on = f.path === active;
        const lines = f.content.split("\n").length;
        return (
          <button
            key={f.path}
            type="button"
            onClick={() => onOpen(f.path)}
            className={`group flex w-full items-center gap-2 rounded-lg py-1.5 pr-2 text-left transition ${
              on ? "bg-[rgb(var(--glow)/0.12)]" : "hover:bg-[rgb(var(--glow)/0.07)]"
            }`}
            style={{ paddingLeft: 26 + depth * 16 }}
          >
            <FileDot language={f.language} />
            <span className={`truncate font-mono text-[12px] ${on ? "text-ink" : "text-ink-2"}`}>{f.path.split("/").pop()}</span>
            {f.path === writing && <span className="text-[10px] text-cyan">writing…</span>}
            <span className="ml-auto shrink-0 text-[10.5px] tabular-nums text-faint">
              {LANG_LABEL[f.language]} · {lines} ln · {formatBytes(new Blob([f.content]).size)}
            </span>
          </button>
        );
      })}
    </>
  );
}

export function FilesTab({
  files,
  active,
  writing,
  onOpen,
  onDownload,
}: {
  files: ModFile[];
  active?: string;
  writing?: string;
  onOpen: (path: string) => void;
  onDownload: () => void;
}) {
  const tree = useMemo(() => buildTree(files), [files]);
  const [collapsed, setCollapsed] = useState<Set<string>>(new Set());
  const total = files.reduce((n, f) => n + new Blob([f.content]).size, 0);
  const lines = files.reduce((n, f) => n + f.content.split("\n").length, 0);

  if (!files.length) return <div className="p-8 text-center text-[13px] text-muted">No files yet — they appear here as Cyrus writes them.</div>;

  return (
    <div className="flex min-h-0 flex-1 flex-col">
      <div className="min-h-0 flex-1 overflow-y-auto px-2 py-2">
        <DirView
          dir={tree}
          depth={0}
          active={active}
          writing={writing}
          collapsed={collapsed}
          toggle={(p) =>
            setCollapsed((s) => {
              const n = new Set(s);
              if (n.has(p)) n.delete(p);
              else n.add(p);
              return n;
            })
          }
          onOpen={onOpen}
        />
      </div>
      <div className="flex items-center gap-3 border-t border-line px-4 py-3 text-[11.5px] text-muted">
        <span>
          {files.length} files · {lines.toLocaleString()} lines · {formatBytes(total)}
        </span>
        <button
          type="button"
          onClick={onDownload}
          disabled={!!writing}
          className="ml-auto inline-flex items-center gap-1.5 rounded-lg bg-[rgb(var(--glow)/0.14)] px-3 py-1.5 text-[12px] font-medium text-ink transition hover:bg-[rgb(var(--glow)/0.22)] disabled:opacity-40"
        >
          <DownloadIcon /> Download .zip
        </button>
      </div>
    </div>
  );
}
