    if (open) {
      setQ("");
      setIdx(0);
      requestAnimationFrame(() => inputRef.current?.focus());
    }
  }, [open]);

  const items = useMemo<Item[]>(() => {
    const st = useStore.getState;
    const out: Item[] = [];
    for (const g of games) {
      out.push({
        id: g.id,
        group: "Games",
        title: g.name,
        hint: g.toolchain,
        rgb: g.rgb,
        icon: <GameEmblem emblem={g.emblem} logo={g.logo} logoTone={g.logoTone} />,
        run: () => select({ level: "game", gameId: g.id }),
        hay: `${g.name} ${g.aliases.join(" ")}`.toLowerCase(),
      });
      const cats = [...new Set([...g.categories, ...mods.filter((m) => m.gameId === g.id).map((m) => m.category)])];
      for (const key of cats) {
        const c = CATEGORY_BY_KEY[key];
        out.push({
          id: `${g.id}:${key}`,
          group: "Categories",
          title: c.label,
          hint: g.name,
          rgb: c.rgb,
          icon: <CategoryIcon k={key} />,
          run: () => select({ level: "category", gameId: g.id, category: key }),
          hay: `${c.label} ${g.name} ${g.short}`.toLowerCase(),
