                  {it.hint && <span className="shrink-0 truncate text-[11.5px] text-muted">{it.hint}</span>}
                  <ArrowRightIcon className={`shrink-0 text-muted transition ${on ? "opacity-100" : "opacity-0"}`} />
                </button>
              </div>
