      onPointerDown={onStageDown}
      onPointerMove={onStageMove}
      onPointerUp={onStageUp}
      onPointerCancel={onStageUp}
    >
      <canvas ref={canvasRef} />
      <div ref={worldRef} className="world">
        <CyrusCore coreRef={coreRef} statusRef={statusRef} onActivate={() => select({ level: "core" })} />
        {graph.nodes
          .filter((n) => n.type !== "core")
          .map((n) => (
            <NodeView
              key={n.id}
              n={n}
              state={nodeStates.get(n.id) ?? "on"}
              selected={selectedId === n.id}
              forging={forgingId === n.id}
              isNew={!initialIds.current!.has(n.id)}
              setRef={setRef}
              onDown={onNodeDown}
              onHover={onHover}
              onKeySelect={selectNode}
            />
          ))}
      </div>
    </div>
  );
}

function Cube() {
  return (
    <svg viewBox="0 0 16 16" className="cube" aria-hidden>
      <path d="M8 1.5 14 4.8v6.4L8 14.5 2 11.2V4.8Z" fill="currentColor" fillOpacity="0.18" stroke="currentColor" strokeWidth="1.2" strokeLinejoin="round" />
      <path d="M2 4.8 8 8l6-3.2M8 8v6.5" fill="none" stroke="currentColor" strokeWidth="1.2" strokeLinejoin="round" />
      <path d="M8 1.5 14 4.8 8 8 2 4.8Z" fill="currentColor" fillOpacity="0.45" />
    </svg>
  );
}

const NodeView = memo(function NodeView({
  n,
  state,
  selected,
  forging,
  isNew,
  setRef,
  onDown,
  onHover,
  onKeySelect,
}: {
  n: LNode;
  state: NodeState;
  selected: boolean;
  forging: boolean;
  isNew: boolean;
  setRef: (id: string, el: HTMLDivElement | null) => void;
  onDown: (e: RPointerEvent, id: string) => void;
  onHover: (id: string | null) => void;
  onKeySelect: (id: string) => void;
}) {
  const kind = n.type === "category" ? "cat" : n.type === "game" ? "game" : "pill";
  const cls = ["node", "tint", `n-${kind}`, n.type === "more" && "is-more", selected && "is-selected", forging && "is-forging", isNew && "is-new"]
    .filter(Boolean)
    .join(" ");
  const handlers = {
    onPointerDown: (e: RPointerEvent) => onDown(e, n.id),
    onPointerEnter: () => onHover(n.id),
    onPointerLeave: () => onHover(null),
    onClick: (e: React.MouseEvent) => {
      // Mouse clicks resolve on pointer-up (so drags don't select); this handles keyboard activation.
      if (e.detail === 0) onKeySelect(n.id);
    },
  };
  const style = { ["--c" as string]: n.rgb };

  if (n.ghost) {
    return (
      <div ref={(el) => setRef(n.id, el)} className={`${cls} is-ghost`} data-state={state} style={style}>
        <button type="button" className="g-orb" aria-label="Add a game branch" {...handlers}>
          <svg viewBox="0 0 24 24" aria-hidden>
            <path d="M12 6.5v11M6.5 12h11" />
          </svg>
        </button>
        <div className="g-name">{n.label}</div>
      </div>
    );
  }
  if (n.type === "game") {
    return (
      <div ref={(el) => setRef(n.id, el)} className={cls} data-state={state} style={style}>
        <div className="g-glow" />
        <button type="button" className="g-orb" aria-label={`Game: ${n.label}`} {...handlers}>
          <GameEmblem emblem={n.emblem ?? "cube"} logo={n.logo} logoTone={n.logoTone} />
        </button>
        <div className="g-name">{n.short ?? n.label}</div>
      </div>
    );
  }
  if (n.type === "category") {
    return (
      <div ref={(el) => setRef(n.id, el)} className={cls} data-state={state} data-side={n.side} style={style}>
        <button type="button" className="c-orb" aria-label={`Category: ${n.label}`} {...handlers}>
          {n.category && <CategoryIcon k={n.category} />}
        </button>
        <div className="c-label">{n.label}</div>
      </div>
    );
  }
  return (
    <div ref={(el) => setRef(n.id, el)} className={cls} data-state={state} data-side={n.side} style={style}>
      <button type="button" className="pill" aria-label={n.type === "more" ? n.label : `Mod: ${n.label}`} {...handlers}>
        {n.type === "more" ? <span className="dots">{n.hidden ? "···" : "+"}</span> : <Cube />}
        <span className="txt">{n.label}</span>
      </button>
    </div>
  );
});
