#!/usr/bin/env python3
"""Scope the Cyrus handoff CSS under .cyrus-root so nothing leaks into the portal.

- every selector gets a `.cyrus-root ` prefix ( `.light X` -> `html[data-theme="light"] .cyrus-root X`,
  `.dark X` -> `html:not([data-theme="light"]) .cyrus-root X`)
- :root / html / body rules map onto .cyrus-root itself
- colliding class names are renamed (glass, btn-ghost, kbd -> cy5-*)
- @keyframes and @property --angle get a cy5- prefix (keyframes are global)
"""
import re
import sys

ROOT = ".cyrus-root"
LIGHT = 'html[data-theme="light"] ' + ROOT
DARK = 'html:not([data-theme="light"]) ' + ROOT
RENAME = {"glass": "cy5-glass", "btn-ghost": "cy5-btn-ghost", "kbd": "cy5-kbd"}


def rename_classes(sel: str) -> str:
    for a, b in RENAME.items():
        sel = re.sub(r"\.%s(?![\w-])" % re.escape(a), "." + b, sel)
    return sel


def scope_one(sel: str) -> str:
    s = rename_classes(sel.strip())
    if not s:
        return s
    if s in (":root", "html", "body", "html,body"):
        return ROOT
    if s == ":root.light":
        return LIGHT
    if s == ":root.dark":
        return DARK
    if s.startswith("::selection"):
        return ROOT + " " + s + ", " + ROOT + s
    m = re.match(r"^\.light(?![\w-])\s*(.*)$", s)
    if m:
        rest = m.group(1)
        return LIGHT + (" " + rest if rest else "")
    m = re.match(r"^\.dark(?![\w-])\s*(.*)$", s)
    if m:
        rest = m.group(1)
        return DARK + (" " + rest if rest else "")
