/* ───────────── Derived helpers ───────────── */

/** Built-in or user-added game by id. */
export function getGame(id: GameId | undefined): Game | undefined {
  if (!id) return undefined;
  return GAME_BY_ID[id] ?? useStore.getState().customGames.find((g) => g.id === id);
}

export function useGames(): Game[] {
  const custom = useStore((s) => s.customGames);
  return useMemo(() => [...GAMES, ...custom], [custom]);
}

export function useGame(id: GameId | undefined): Game | undefined {
  const games = useGames();
  return useMemo(() => (id ? games.find((g) => g.id === id) : undefined), [games, id]);
}

const seedCache = new Map<string, ModVersion[]>();

export function versionsOf(mod: Mod | undefined, userVersions: Record<string, ModVersion[]>): ModVersion[] {
  if (!mod) return [];
  let base: ModVersion[] = [];
  if (mod.seed) {
    base = seedCache.get(mod.id) ?? seedVersions(mod);
    seedCache.set(mod.id, base);
  }
  return [...base, ...(userVersions[mod.id] ?? [])];
}

export function useAllMods(): Mod[] {
  const userMods = useStore((s) => s.userMods);
  return useMemo(() => [...SEED_MODS, ...userMods], [userMods]);
}

export function findMod(id: string | undefined): Mod | undefined {
  if (!id) return undefined;
  return SEED_MODS.find((m) => m.id === id) ?? useStore.getState().userMods.find((m) => m.id === id);
}

export function useMod(id: string | undefined) {
  const userMods = useStore((s) => s.userMods);
  return useMemo(() => (id ? (SEED_MODS.find((m) => m.id === id) ?? userMods.find((m) => m.id === id)) : undefined), [id, userMods]);
}

export function useModVersions(mod: Mod | undefined) {
  const userVersions = useStore((s) => s.userVersions);
  const activeVersion = useStore((s) => s.activeVersion);
  return useMemo(() => {
    const versions = versionsOf(mod, userVersions);
    const activeId = mod ? (activeVersion[mod.id] ?? versions[versions.length - 1]?.id) : undefined;
    const active = versions.find((v) => v.id === activeId) ?? versions[versions.length - 1];
    return { versions, active };
  }, [mod, userVersions, activeVersion]);
}

export const isJobLive = (job: Job | null) =>
  !!job && (job.status === "connecting" || job.status === "thinking" || job.status === "writing");

