// Cyrus v5: a REAL build (the Minecraft plugin builder on the mod-builder VM) told as the studio's
// forge event stream (lib/cyrus/types.ts GenEvent, handoff START-HERE §6), so the network's beams,
// the thinking trace and the live code panel animate on real progress:
//   start -> build -> think(read) -> route -> think(stage)... file / chunk / file-set / file-done ... -> done | error
// Stages come from the build row (synced from the service), code from the service's live view
// (the file being written right now + the workspace files). Server only.
//
// The build runs on its own: if the client goes away the stream stops, the build does not (the
// worker sweep keeps syncing it), and GET /api/cyrus/generate?follow=<id> picks it up again.
import type { ModBuild } from "@prisma/client";
import { db } from "../db";
import { svcLive, svcSource } from "../modbuilder/client";
import { syncBuild, toView } from "../modbuilder/store";
import { isTerminal, type ModBuildView } from "../modbuilder/types";
import { serviceBuildId } from "../cyrus-mods/registry";
import { readCyrusMeta } from "./meta";
import { GAMES } from "./data";
import { deriveReal, realModId, realNotes, visibleSource } from "./real";
import { languageForPath } from "./engine/kit";
import type { CategoryKey, GenEvent, ModelId } from "./types";

const REAL_GAME = GAMES.find((g) => g.real) ?? GAMES[0];
const sleep = (ms: number, signal?: AbortSignal) =>
  new Promise<void>((r) => {
    const t = setTimeout(r, ms);
    signal?.addEventListener("abort", () => { clearTimeout(t); r(); }, { once: true });
  });

/** What the studio calls each build stage (customer voice; never names a model). */
const STAGE: Record<string, { label: string; detail: (b: ModBuild) => string }> = {
  queued: { label: "Waiting for a free builder", detail: () => "Cyrus builds two mods at a time in the preview" },
  planning: { label: "Planning the plugin", detail: (b) => `Paper ${b.mcVersion} · Java 21 · commands, events, config` },
  coding: { label: "Writing the code", detail: () => "src/main/java" },
  compiling: { label: "Compiling into a real plugin", detail: (b) => `Gradle · Paper API ${b.mcVersion}` },
  repairing: { label: "Fixing what the compiler found", detail: () => "Cyrus reads the errors and repairs its own code" },
  scanning: { label: "Safety check", detail: () => "No internet, no system access, no surprises" },
};
const NOISE = new Set(["Error details", "API lookup"]);

export type RealRoute = { gameId: string; category: CategoryKey; modName: string; modId: string; summary: string };

/** Where a build sits on the network: same derivation the client uses (lib/cyrus/real.ts). */
export async function routeOfBuild(userId: string, build: ModBuild): Promise<RealRoute> {
  const rows = await db.modBuild.findMany({ where: { userId }, orderBy: { createdAt: "desc" }, take: 200 });
  if (!rows.some((r) => r.id === build.id)) rows.push(build);
  const model = deriveReal(rows.map(toView), REAL_GAME);
  const rootId = build.rootBuildId ?? build.id;
  const mod = model.mods.find((m) => m.id === realModId(rootId));
  return {
    gameId: REAL_GAME.id,
    category: mod?.category ?? "mechanics",
    modName: mod?.name ?? "New plugin",
    modId: realModId(rootId),
    summary: mod?.summary ?? build.prompt.slice(0, 140),
  };
}

async function sourceText(id: string, path: string): Promise<string | null> {
  try {
    const r = await svcSource(id, path);
    return r.ok ? await r.text() : null;
  } catch {
    return null;
  }
}

export async function* followBuild(buildId: string, opts: { userId: string; refining: boolean; signal: AbortSignal; maxMs?: number }): AsyncGenerator<GenEvent> {
  const { signal } = opts;
  let row = await db.modBuild.findUnique({ where: { id: buildId } });
  if (!row || row.userId !== opts.userId) {
    yield { type: "error", message: "That build isn't yours or no longer exists." };
    return;
  }
  const hold = await db.cyrusTokenReservation.findUnique({ where: { buildId } }).catch(() => null);
  const model: ModelId = readCyrusMeta(row.cyrus).model ?? "saka";
  yield { type: "start", jobId: row.id, model, credits: hold?.amount ?? 0, real: true };
  yield { type: "build", build: toView(row) };

  const ask = (row.changeRequest || row.prompt).replace(/\s+/g, " ").trim();
  yield { type: "think", id: "read", label: opts.refining ? "Reading the current build" : "Reading your request", detail: `“${ask.length > 64 ? ask.slice(0, 63) + "…" : ask}”` };
  const route = await routeOfBuild(opts.userId, row);
  yield { type: "route", ...route, tags: [] };
  yield { type: "think-done", id: "read" };

  const deadline = Date.now() + (opts.maxMs ?? 20 * 60_000);
  let stage: string | null = null;
  let seenEvents = 0;
  let lastSync = 0;
  let lastSent = Date.now();
  const files = new Map<string, { hash: string; content: string }>();
  const announced = new Set<string>();
  let draft: { path: string; seq: number; op: "write" | "edit"; text: string; done: boolean } | null = null;

  const announce = function* (path: string): Generator<GenEvent> {
    if (announced.has(path)) return;
    announced.add(path);
    yield { type: "think", id: `w:${path}`, label: `Writing ${path.split("/").pop()}`, detail: path };
    yield { type: "file", path, language: languageForPath(path) };
  };

  while (!signal.aborted && Date.now() < deadline) {
    const out: GenEvent[] = [];
    // 1) the build row (stage, events) — synced every ~2 s
    if (Date.now() - lastSync > 1800) {
      lastSync = Date.now();
      try { row = await syncBuild(row!); } catch { /* the service may be busy; try again */ }
    }
    const b = row!;
    if (!isTerminal(b.status) && b.status !== stage) {
      if (stage) out.push({ type: "think-done", id: `st:${stage}` });
      stage = b.status;
      const st = STAGE[b.status] ?? { label: "Working", detail: () => "" };
      out.push({ type: "think", id: `st:${stage}`, label: st.label, detail: st.detail(b) });
    }
    const events = ((b.result as { events?: { stage: string; message: string }[] } | null)?.events ?? []).filter((e) => e.message && !NOISE.has(e.message));
    if (events.length > seenEvents && stage && !isTerminal(b.status)) {
      const last = events[events.length - 1];
      out.push({ type: "think", id: `st:${stage}`, label: (STAGE[stage] ?? { label: "Working" }).label, detail: last.message.slice(0, 160) });
    }
    seenEvents = events.length;
    if (isTerminal(b.status)) {
      for (const e of out) yield e;
      break;
    }

    // 2) the code, live
    const live = await svcLive(b.id, draft && !draft.done ? draft.path : undefined, draft && !draft.done ? draft.text.length : 0, draft?.seq ?? 0).catch(() => null);
    if (live?.live) {
      const d = live.draft;
      if (d) {
        const same = draft && draft.path === d.path && draft.seq === d.seq;
        if (!same) {
          if (draft && !draft.done && draft.op === "write") { out.push({ type: "file-done", path: draft.path }, { type: "think-done", id: `w:${draft.path}` }); }
          draft = { path: d.path, seq: d.seq, op: d.op, text: "", done: false };
          if (d.op === "write") {
            const fresh = !announced.has(d.path);
            out.push(...announce(d.path));
            if (!fresh) out.push({ type: "file-set", path: d.path, content: "" }, { type: "think", id: `w:${d.path}`, label: `Rewriting ${d.path.split("/").pop()}`, detail: d.path });
          } else {
            out.push(...announce(d.path));
            out.push({ type: "think", id: `w:${d.path}`, label: `Editing ${d.path.split("/").pop()}`, detail: d.path });
          }
        }
        const cur = draft!;
        if (cur.op === "write") {
          const next = (d.from <= cur.text.length ? cur.text.slice(0, d.from) : cur.text) + d.text;
          if (d.from === cur.text.length) { if (d.text) out.push({ type: "chunk", path: d.path, text: d.text }); }
          else out.push({ type: "file-set", path: d.path, content: next });
          cur.text = next;
        } else {
          cur.text = (d.from <= cur.text.length ? cur.text.slice(0, d.from) : cur.text) + d.text;
        }
        if (d.done && !cur.done) {
          cur.done = true;
          if (cur.op === "write") out.push({ type: "file-done", path: cur.path });
          out.push({ type: "think-done", id: `w:${cur.path}` });
        }
      }
      // workspace files that landed or changed (an edit, or a file written while we weren't looking)
      for (const f of live.files) {
        if (files.get(f.path)?.hash === f.hash) continue;
        if (draft && !draft.done && draft.path === f.path) continue; // still streaming it
        const text = await sourceText(b.id, f.path);
        if (text === null) continue;
        const known = files.get(f.path)?.content ?? (draft?.path === f.path ? draft.text : null);
        files.set(f.path, { hash: f.hash, content: text });
        if (!announced.has(f.path)) {
          out.push(...announce(f.path));
          out.push({ type: "chunk", path: f.path, text }, { type: "file-done", path: f.path }, { type: "think-done", id: `w:${f.path}` });
        } else if (known !== text) {
          out.push({ type: "file-set", path: f.path, content: text });
        }
      }
    }
    if (out.length) lastSent = Date.now();
    else if (Date.now() - lastSent > 8000) { out.push({ type: "ping" }); lastSent = Date.now(); }
    for (const e of out) yield e;
    await sleep(900, signal);
  }
  if (signal.aborted || !row || !isTerminal(row.status)) return;

  const view: ModBuildView = toView(row);
  if (row.status === "failed") {
    yield { type: "error", message: row.error || "This version didn't build. Any tokens it held go back to you." };
    return;
  }
  // The finished source: anything not seen live (resources, a last edit) lands now.
  const src = await serviceBuildId(row.id);
  for (const f of visibleSource(view.result?.files ?? [])) {
    if (signal.aborted) return;
    const text = await sourceText(src, f.path);
    if (text === null) continue;
    if (!announced.has(f.path)) {
      for (const e of announce(f.path)) yield e;
      yield { type: "chunk", path: f.path, text };
      yield { type: "file-done", path: f.path };
      yield { type: "think-done", id: `w:${f.path}` };
    } else if (files.get(f.path)?.content !== text && !(draft?.path === f.path && draft.text === text)) {
      yield { type: "file-set", path: f.path, content: text };
    }
  }
  yield { type: "think", id: "pkg", label: "Compiled and safety-checked", detail: `${row.jarName ?? "plugin.jar"} · Paper ${row.mcVersion}` };
  yield { type: "think-done", id: "pkg" };
  const settled = await db.cyrusTokenReservation.findUnique({ where: { buildId: row.id } }).catch(() => null);
  yield { type: "build", build: view };
  yield { type: "done", summary: view.result?.summary?.tagline || view.result?.summary?.text || "Ready to install", notes: realNotes(view), tokens: settled?.charged ?? undefined };
}

