      prompt: text,
      model: model.id,
      images: images.map((i) => i.url),
      credits: 0,
      refining: !!refineMod,
      version: refineMod ? prior.length + 1 : 1,
      steps: [],
      files: [],
      startedAt: Date.now(),
    },
  });
