"use client";

// The forge client (handoff lib/forge.ts): streams /api/cyrus/generate into the store and drives
// the network's beams and packets. Nxeon: a Minecraft forge is a REAL build (the stream carries its
// real progress and code, tokens are held and settled by the economy); every other game is the
// handoff's template preview. No local credits.
import { cyrusTokens } from "@/components/cyrus-tokens";
import { CATEGORY_BY_KEY, MODEL_BY_ID, categoryNodeId } from "./data";
import { diffStats } from "./engine";
import { fx } from "./fx";
import { isRealModId, realModId } from "./real";
import { CORE_ID, findMod, getGame, isJobLive, useStore, versionsOf, type Job } from "./store";
import type { GenEvent, Mod, ModVersion, ModelId } from "./types";

let controller: AbortController | null = null;

const patchJob = (fn: (job: Job) => Partial<Job>) =>
  useStore.setState((s) => (s.job ? { job: { ...s.job, ...fn(s.job) } } : {}));

export function cancelForge() {
  const job = useStore.getState().job;
  // A real build is stopped on the builder too (its held tokens are settled by the economy).
  if (job?.buildId && isJobLive(job)) void fetch(`/api/mod-builder/builds/${job.buildId}/cancel`, { method: "POST" }).catch(() => {});
  controller?.abort();
}

export type ForgeImage = { url: string; uploadId?: string };

type Ctx = { createdModId: string | null; path: string[]; rgb: string; finished: boolean; startedAt: number };

function makeHandler(ctx: Ctx) {
  // Chunks arrive faster than React needs to paint; batch them per animation frame.
  const pending = new Map<string, string>();
  let raf = 0;
  const flush = () => {
    raf = 0;
    if (!pending.size) return;
    const batch = new Map(pending);
    pending.clear();
    patchJob((job) => ({ files: job.files.map((f) => (batch.has(f.path) ? { ...f, content: f.content + batch.get(f.path) } : f)) }));
  };
  const stop = () => cancelAnimationFrame(raf);

  const handle = (ev: GenEvent) => {
    switch (ev.type) {
      case "start":
        patchJob(() => ({ id: ev.jobId, status: "thinking", credits: ev.credits, real: !!ev.real, ...(ev.real ? { buildId: ev.jobId } : {}) }));
        break;

      case "build":
        useStore.getState().upsertReal([ev.build]);
        patchJob(() => ({ buildId: ev.build.id, real: true }));
        break;

      case "ping":
        break;

      case "think":
        patchJob((job) => ({
          steps: [
            ...job.steps.filter((s) => s.id !== ev.id),
            { id: ev.id, label: ev.label, detail: ev.detail, done: false, startedAt: job.steps.find((s) => s.id === ev.id)?.startedAt ?? Date.now() },
          ],
        }));
        fx.ripple();
        if (ctx.path.length) fx.packets(ctx.path.slice(0, 3), 1, { rgb: ctx.rgb, speed: 1.4 });
        break;

      case "think-done":
        patchJob((job) => ({ steps: job.steps.map((s) => (s.id === ev.id ? { ...s, done: true, endedAt: Date.now() } : s)) }));
        break;

      case "route": {
        const game = getGame(ev.gameId);
        ctx.rgb = game?.rgb ?? ctx.rgb;
        ctx.path = [CORE_ID, ev.gameId, categoryNodeId(ev.gameId, ev.category), ev.modId];
        patchJob(() => ({ gameId: ev.gameId, category: ev.category, modId: ev.modId, modName: ev.modName }));
        if (!findMod(ev.modId) && !isRealModId(ev.modId)) {
          const mod: Mod = { id: ev.modId, gameId: ev.gameId, category: ev.category, name: ev.modName, summary: ev.summary, tags: ev.tags, createdAt: Date.now(), versions: [] };
          ctx.createdModId = ev.modId;
          useStore.setState((s) => ({ userMods: [...s.userMods, mod] }));
        }
        useStore.getState().select({ level: "mod", gameId: ev.gameId, category: ev.category, modId: ev.modId }, { openPanel: true, focus: "path" });
        useStore.setState({ panelTab: "code" });
        fx.setMode("forging");
        fx.startStream(ctx.path, ctx.rgb);
        fx.packets(ctx.path, 4, { rgb: ctx.rgb, speed: 1.2, size: 1.4 });
        break;
      }

      case "file":
        patchJob((job) => ({
          status: "writing",
          activeFile: ev.path,
          files: job.files.some((f) => f.path === ev.path) ? job.files : [...job.files, { path: ev.path, language: ev.language, content: "" }],
        }));
        useStore.setState({ activeFile: ev.path });
        break;

      case "chunk":
        pending.set(ev.path, (pending.get(ev.path) ?? "") + ev.text);
        if (!raf) raf = requestAnimationFrame(flush);
        break;

      case "file-set":
        // the builder rewrote or edited a file in place: replace it (after any queued chunks)
        stop();
        flush();
        patchJob((job) => ({ files: job.files.map((f) => (f.path === ev.path ? { ...f, content: ev.content } : f)), activeFile: ev.path }));
        fx.packets(ctx.path, 1, { rgb: ctx.rgb, speed: 1.6 });
        break;

      case "file-done":
        fx.packets(ctx.path, 2, { rgb: ctx.rgb, speed: 1.6 });
        break;

      case "done": {
        stop();
        flush();
        ctx.finished = true;
        const s = useStore.getState();
        const job = s.job!;
        const seconds = ((performance.now() - ctx.startedAt) / 1000).toFixed(1);
        if (job.real && job.buildId) {
          // The version IS the real build: keep the streamed code as its files and re-read the
          // account (build list, token balance).
          s.seedRealFiles(job.buildId, job.files);
          useStore.setState((st) => ({ job: st.job ? { ...st.job, status: "done", finishedAt: Date.now() } : null }));
          void s.refreshReal();
          void cyrusTokens.refresh();
          const mod = findMod(job.modId);
          const n = mod ? versionsOf(mod, s.userVersions).findIndex((v) => v.id === job.buildId) + 1 : 0;
          finishFx(job.modId ?? "", ctx);
          s.toast({
            tone: "success",
            title: `${mod?.name ?? job.modName ?? "Your plugin"}${n ? ` v${n}` : ""} is ready`,
            body: `${job.files.length} files · ${ev.tokens !== undefined ? `${ev.tokens.toLocaleString("en-US")} tokens · ` : ""}${seconds}s · compiled and safety-checked`,
            rgb: ctx.rgb,
          });
          break;
        }
        const mod = findMod(job.modId);
        if (!mod) break;
        const prev = versionsOf(mod, s.userVersions);
        const prevActive = prev.find((v) => v.id === s.activeVersion[mod.id]) ?? prev[prev.length - 1];
        const n = prev.length + 1;
        const { additions, deletions } = diffStats(prevActive?.files, job.files);
        const version: ModVersion = {
          id: `${mod.id}@v${n}-${Date.now().toString(36)}`,
          label: `v${n}`,
          createdAt: Date.now(),
          model: job.model,
          credits: 0,
          prompt: job.prompt,
          summary: ev.summary,
          files: job.files,
          additions,
          deletions,
        };
        useStore.setState((st) => ({
          userVersions: { ...st.userVersions, [mod.id]: [...(st.userVersions[mod.id] ?? []), version] },
          activeVersion: { ...st.activeVersion, [mod.id]: version.id },
          aiNotes: { ...st.aiNotes, [mod.id]: ev.notes },
          job: st.job ? { ...st.job, status: "done", finishedAt: Date.now() } : null,
        }));
        finishFx(mod.id, ctx);
        s.toast({ tone: "success", title: `${mod.name} ${version.label} forged`, body: `${job.files.length} files · template preview, no tokens · ${seconds}s`, rgb: ctx.rgb });
        break;
      }

      case "error":
        throw new Error(ev.message);
    }
  };
  return { handle, stop };
}

function finishFx(modId: string, ctx: Ctx) {
  fx.stopStream();
  fx.setMode("idle");
  fx.burst(modId, ctx.rgb);
  fx.packets([...ctx.path].reverse(), 5, { rgb: "196 181 253", speed: 1.3, gap: 0.12 });
  window.setTimeout(() => fx.ripple(true), 900);
}

async function readStream(res: Response, handle: (ev: GenEvent) => void) {
  const reader = res.body!.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    buffer += decoder.decode(value, { stream: true });
    let nl: number;
    while ((nl = buffer.indexOf("\n")) >= 0) {
      const line = buffer.slice(0, nl).trim();
      buffer = buffer.slice(nl + 1);
      if (line) handle(JSON.parse(line) as GenEvent);
    }
  }
}

class HttpError extends Error {
  constructor(message: string, readonly json: Record<string, unknown>) {
    super(message);
  }
}

/** Run one forge request, and keep following a real build if the connection drops. */
async function run(open: (signal: AbortSignal) => Promise<Response>, ctx: Ctx) {
  const { handle, stop } = makeHandler(ctx);
  controller = new AbortController();
  const signal = controller.signal;
  try {
    let res = await open(signal);
    for (let attempt = 0; ; attempt++) {
      if (!res.ok || !res.body) {
        const j = (await res.json().catch(() => ({ error: res.statusText }))) as Record<string, unknown>;
        throw new HttpError(String(j.error ?? "The forge did not respond"), j);
      }
      await readStream(res, handle);
      if (ctx.finished) break;
      // A real build outlives the connection: re-attach (the server re-sends the code so far).
      const job = useStore.getState().job;
      if (!job?.buildId || attempt >= 4 || signal.aborted) throw new Error("The stream ended before the mod was packaged");
      await new Promise((r) => setTimeout(r, 1200 * (attempt + 1)));
      patchJob(() => ({ files: [], steps: [] }));
      res = await fetch(`/api/cyrus/generate?follow=${encodeURIComponent(job.buildId)}`, { signal });
    }
  } catch (err) {
    stop();
    const aborted = signal.aborted;
    const s = useStore.getState();
    const real = !!s.job?.real || !!s.job?.buildId;
    fx.stopStream();
    fx.setMode("idle");
    if (err instanceof HttpError) cyrusTokens.handleBuildError(err.json);
    useStore.setState((st) => ({
      // A brand-new template mod that never finished packaging shouldn't linger as an empty node.
      userMods: ctx.createdModId ? st.userMods.filter((m) => m.id !== ctx.createdModId) : st.userMods,
      job: st.job ? { ...st.job, status: aborted ? "cancelled" : "error", error: aborted ? undefined : String((err as Error).message), finishedAt: Date.now() } : null,
    }));
    if (ctx.createdModId) useStore.getState().select({ level: "category", gameId: s.job?.gameId, category: s.job?.category }, { openPanel: false });
    if (real) {
      void s.refreshReal();
      void cyrusTokens.refresh();
    }
    s.toast(
      aborted
        ? { tone: "info", title: real ? "Build stopped" : "Forge stopped", body: real ? "Cyrus stopped the build. Tokens it didn't use go back to you." : "Nothing was saved." }
        : { tone: "error", title: real ? "Didn't build" : "Forge failed", body: (err as Error).message },
    );
  } finally {
    controller = null;
  }
}

export async function forge(prompt: string, images: ForgeImage[] = []) {
  const state = useStore.getState();
  if (isJobLive(state.job)) return;
  const text = prompt.trim();
  if (!text) return;
  const model = MODEL_BY_ID[state.model];

  const sel = state.selection;
  const picked = sel.level === "mod" ? findMod(sel.modId) : undefined;
  // An idea pill is a prompt, not a mod: a forge from it is a brand-new mod in its category.
  const refineMod = picked?.idea ? undefined : picked;
  if (refineMod?.real && !refineMod.real.headBuildId) {
    state.toast({
      tone: "error",
      title: "Nothing to change yet",
      body: refineMod.real.running ? "Cyrus is still building this mod. Ask for the next change when it's ready." : "This mod has no version that built. Describe it again to forge a new one.",
    });
    return;
  }
  const prior = refineMod ? versionsOf(refineMod, state.userVersions) : [];
  const context = refineMod
    ? { gameId: refineMod.gameId, category: refineMod.category, modId: refineMod.id, modName: refineMod.name, version: prior.length + 1 }
    : { gameId: sel.gameId, category: sel.category };

  const ctx: Ctx = { createdModId: null, path: [], rgb: "167 139 250", finished: false, startedAt: performance.now() };
  useStore.setState({
    job: {
      id: "pending",
      status: "connecting",
      prompt: text,
      model: model.id,
      images: images.map((i) => i.url),
      credits: 0,
      refining: !!refineMod,
      version: refineMod ? prior.length + 1 : 1,
      steps: [],
      files: [],
      startedAt: Date.now(),
    },
  });
  fx.setMode("thinking");
  fx.ripple(true);

  await run(
    (signal) =>
      fetch("/api/cyrus/generate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          prompt: text,
          model: model.id,
          images: images.length,
          attachmentIds: images.map((i) => i.uploadId).filter(Boolean),
          mcVersion: state.mcVersion,
          context,
          games: state.customGames,
        }),
        signal,
      }),
    ctx,
  );
}

/** Re-attach to a real build that is still running (page load, a build started elsewhere). */
export async function followForge(buildId: string) {
  const state = useStore.getState();
  if (isJobLive(state.job)) return;
  const b = state.realBuilds.find((x) => x.id === buildId);
  if (!b) return;
  const mod = findMod(realModId(b.rootBuildId ?? b.id));
  const n = mod ? versionsOf(mod, state.userVersions).findIndex((v) => v.id === buildId) + 1 : 1;
  useStore.setState({
    job: {
      id: buildId,
      status: "connecting",
      prompt: b.changeRequest || b.prompt,
      model: ((b.cyrus as { model?: ModelId } | null)?.model ?? "saka") as ModelId,
      images: [],
      credits: 0,
      refining: !!b.baseBuildId,
      version: Math.max(1, n),
      steps: [],
      files: [],
      startedAt: Date.parse(b.createdAt) || Date.now(),
      buildId,
      real: true,
    },
  });
  fx.setMode("thinking");
  const ctx: Ctx = { createdModId: null, path: [], rgb: "167 139 250", finished: false, startedAt: performance.now() };
  await run((signal) => fetch(`/api/cyrus/generate?follow=${encodeURIComponent(buildId)}`, { signal }), ctx);
}

/** Utility for UI: the category label + game for a job, once routed. */
export function jobRouteLabel(job: Job) {
  if (!job.gameId || !job.category) return null;
  return `${getGame(job.gameId)?.short ?? "Game"} › ${CATEGORY_BY_KEY[job.category].label}`;
}

