/** The portal's theme (components/nx/ThemeToggle.tsx writes html[data-theme]); dark by default. */
export const portalTheme = (): "light" | "dark" =>
  typeof document !== "undefined" && document.documentElement.getAttribute("data-theme") === "light" ? "light" : "dark";

/**
 * Nxeon boot for every Cyrus page: local state is kept per account (`cyrus-state-v1:<userId>`,
 * template-game mods, layout, core style, model), rehydrated after hydration so server and client
 * markup match; and the studio's `theme` mirrors the PORTAL theme, live.
 */
export function useCyrusBoot(userId: string) {
  useEffect(() => {
    // Imported lazily so this file stays free of the store for the components that only need hooks.
    let off = () => {};
    void import("./store").then(({ useStore }) => {
      useStore.persist.setOptions({ name: `cyrus-state-v1:${userId}` });
      void useStore.persist.rehydrate();
      useStore.setState({ userId, theme: portalTheme() });
      const mo = new MutationObserver(() => {
        const t = portalTheme();
        if (useStore.getState().theme !== t) useStore.setState({ theme: t });
      });
      mo.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });
      off = () => mo.disconnect();
    });
    return () => off();
  }, [userId]);
}
