  const select = useStore((s) => s.select);
  const cat = CATEGORY_BY_KEY[mod.category];
  return (
    <button
      type="button"
      onClick={() => select({ level: "mod", gameId: mod.gameId, category: mod.category, modId: mod.id }, { openPanel: true })}
      className="tint animate-rise group flex w-full items-start gap-3 rounded-xl border border-cy-line p-3 text-left transition hover:-translate-y-0.5 hover:border-cy-line-2 hover:bg-[rgb(var(--glow)/0.06)]"
