    >
      <span
        className="mt-0.5 h-2.5 w-2.5 shrink-0 rounded-full"
        style={{ background: `rgb(${cat.rgb})`, boxShadow: `0 0 10px rgb(${cat.rgb} / 0.8)` }}
      />
      <span className="min-w-0 flex-1">
        <span className="block font-cy-display text-[13.5px] font-semibold text-cy-ink">{mod.name}</span>
        <span className="mt-0.5 block line-clamp-2 text-[12px] leading-snug text-cy-ink-2">{mod.summary}</span>
        <span className="mt-2 flex flex-wrap gap-1">
          {mod.tags.slice(0, 3).map((t) => (
            <span key={t} className="rounded-md px-1.5 py-0.5 text-[10px]" style={{ color: "var(--cc-ink)", background: `rgb(${cat.rgb} / 0.1)` }}>
              {t}
            </span>
          ))}
        </span>
      </span>
      <ArrowRightIcon className="mt-1 shrink-0 text-cy-muted opacity-0 transition group-hover:translate-x-0.5 group-hover:opacity-100" />
    </button>
  );
}

