// THROWAWAY local stand-in for the mod builder service (verification on node-2 only; never
// committed). Speaks the same HTTP the portal's lib/modbuilder/client.ts calls, so the portal's
// REAL code paths (createModBuild, syncBuild, the jar store, /live, /source) run unchanged.
// A new build walks queued -> planning -> coding (streams its files) -> compiling -> scanning -> succeeded.
import { createServer } from "node:http";
import { createHash } from "node:crypto";

const PORT = Number(process.env.MOCK_PORT || 7399);
const KEY = process.env.MODBUILDER_API_KEY || "local-mock-key";
const builds = new Map();
const T = { queued: 1.5, planning: 5, coding: 30, compiling: 35, scanning: 38 };

const pascal = (s) => (s.match(/[A-Za-z0-9]+/g) || ["Plugin"]).slice(0, 3).map((w) => w[0].toUpperCase() + w.slice(1).toLowerCase()).join("");
function nameFor(prompt) {
  const p = prompt.replace(/^(a|an|the)\s+/i, "").replace(/^minecraft paper plugin:\s*/i, "");
  const head = p.split(/[:.,]| for | that | with /i)[0];
  return pascal(head.replace(/\b(minecraft|paper|plugin|custom)\b/gi, " ")) || "Plugin";
}
function sourcesFor(name, prompt) {
  const pkg = `dev.cyrus.${name.toLowerCase()}`;
  const base = `src/main/java/dev/cyrus/${name.toLowerCase()}`;
  const main = `package ${pkg};

import org.bukkit.Bukkit;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * ${name}: ${prompt.slice(0, 90).replace(/\*\//g, "")}
 * Built by Cyrus for Paper.
 */
public final class ${name}Plugin extends JavaPlugin {
    private ${name}Settings settings;

    @Override
    public void onEnable() {
        saveDefaultConfig();
        settings = ${name}Settings.load(getConfig());
        Bukkit.getPluginManager().registerEvents(new ${name}Listener(this), this);
        getLogger().info("${name} enabled with " + settings.describe());
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (args.length == 1 && args[0].equalsIgnoreCase("reload")) {
            if (!sender.hasPermission("${name.toLowerCase()}.admin")) {
                sender.sendMessage("You don't have permission to do that.");
                return true;
            }
            reloadConfig();
            settings = ${name}Settings.load(getConfig());
            sender.sendMessage("${name} reloaded.");
            return true;
        }
        if (sender instanceof Player player) {
            player.sendMessage(settings.greeting());
            return true;
        }
        sender.sendMessage("Run this in game.");
        return true;
    }

    public ${name}Settings settings() {
        return settings;
    }
}
`;
  const listener = `package ${pkg};

import org.bukkit.Particle;
import org.bukkit.entity.LivingEntity;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.entity.EntityDamageByEntityEvent;
import org.bukkit.potion.PotionEffect;
import org.bukkit.potion.PotionEffectType;

final class ${name}Listener implements Listener {
    private final ${name}Plugin plugin;

    ${name}Listener(${name}Plugin plugin) {
        this.plugin = plugin;
    }

    @EventHandler(ignoreCancelled = true)
    public void onHit(EntityDamageByEntityEvent event) {
        if (!(event.getDamager() instanceof Player player)) return;
        if (!(event.getEntity() instanceof LivingEntity target)) return;
        ${name}Settings s = plugin.settings();
        if (!player.hasPermission("${name.toLowerCase()}.use")) return;
        if (player.getFallDistance() <= 0 || player.isOnGround()) return; // critical hits only
        target.addPotionEffect(new PotionEffect(PotionEffectType.SLOWNESS, s.slowTicks(), s.slowLevel()));
        target.setFreezeTicks(Math.max(target.getFreezeTicks(), s.freezeTicks()));
        target.getWorld().spawnParticle(Particle.SNOWFLAKE, target.getLocation().add(0, 1, 0), 24, 0.4, 0.6, 0.4, 0.02);
    }
}
`;
  const settings = `package ${pkg};

import org.bukkit.configuration.file.FileConfiguration;

record ${name}Settings(int slowTicks, int slowLevel, int freezeTicks, String greeting) {
    static ${name}Settings load(FileConfiguration c) {
        return new ${name}Settings(
            c.getInt("slow.ticks", 60),
            c.getInt("slow.level", 1),
            c.getInt("freeze.ticks", 140),
            c.getString("messages.greeting", "${name} is ready.")
        );
    }

    String describe() {
        return "slow " + slowTicks + "t, freeze " + freezeTicks + "t";
    }
}
`;
  const yml = `name: ${name}
version: 1.0.0
main: ${pkg}.${name}Plugin
api-version: '1.21'
description: Built by Cyrus
commands:
  ${name.toLowerCase()}:
    description: ${name} commands
    usage: /${name.toLowerCase()} reload
permissions:
  ${name.toLowerCase()}.use:
    default: true
  ${name.toLowerCase()}.admin:
    default: op
`;
  const cfg = `# ${name} settings\nslow:\n  ticks: 60\n  level: 1\nfreeze:\n  ticks: 140\nmessages:\n  greeting: "${name} is ready."\n`;
  return [
    { path: `${base}/${name}Plugin.java`, text: main },
    { path: `${base}/${name}Listener.java`, text: listener },
    { path: `${base}/${name}Settings.java`, text: settings },
    { path: "src/main/resources/plugin.yml", text: yml },
    { path: "src/main/resources/config.yml", text: cfg },
  ];
}
const hash = (t) => createHash("sha256").update(t).digest("hex").slice(0, 12);
const jarBytes = (b) => Buffer.from(`PK\u0003\u0004 mock jar for ${b.id} ${b.name}`);

function stageAt(b) {
  if (b.cancelled) return "failed";
  if (b.done) return "succeeded";
  const s = (Date.now() - b.created) / 1000;
  for (const k of ["queued", "planning", "coding", "compiling", "scanning"]) if (s < T[k]) return k;
  return "succeeded";
}
function codingProgress(b) {
  // the share of all source written so far, during coding
  const s = (Date.now() - b.created) / 1000;
  return Math.max(0, Math.min(1, (s - T.planning) / (T.coding - T.planning)));
}
function view(b) {
  const status = stageAt(b);
  const at = (sec) => new Date(b.created + sec * 1000).toISOString();
  const ev = [{ at: at(0), stage: "queued", message: "Queued" }];
  const s = (Date.now() - b.created) / 1000;
  if (b.done || s > T.queued) ev.push({ at: at(T.queued), stage: "planning", message: `Planning ${b.name} for Paper ${b.mcVersion}` });
  if (b.done || s > T.planning) ev.push({ at: at(T.planning), stage: "coding", message: `Writing ${b.name}Plugin.java` });
  if (b.done || s > T.planning + 8) ev.push({ at: at(T.planning + 8), stage: "coding", message: `Wrote ${b.name}Listener.java` });
  if (b.done || s > T.coding) ev.push({ at: at(T.coding), stage: "compiling", message: `Compiling against Paper ${b.mcVersion}` });
  if (b.done || s > T.compiling) ev.push({ at: at(T.compiling), stage: "scanning", message: "Running the safety check" });
  const ok = status === "succeeded";
  if (ok) ev.push({ at: at(T.scanning), stage: "succeeded", message: `Ready: ${b.name}-1.0.0.jar` });
  const jar = ok ? jarBytes(b) : null;
  return {
    id: b.id, status, error: status === "failed" ? "Stopped." : null, errorCode: status === "failed" ? "cancelled" : null,
    attempts: 1, repairs: 0, costUsd: ok ? 0.104 : 0, durationMs: ok ? T.scanning * 1000 : null, pluginName: b.name, version: "1.0.0",
    jar: jar ? { name: `${b.name}-1.0.0.jar`, size: jar.length, sha256: createHash("sha256").update(jar).digest("hex") } : null,
    summary: ok ? { tagline: b.tagline, text: `${b.name} adds ${b.prompt.slice(0, 120)}`, howToUse: [`Drop the jar into plugins/ and restart`, `/${b.name.toLowerCase()} reload reloads config.yml`], limitations: ["Critical hits only"], changes: b.changeRequest || "" } : null,
    commands: ok ? [{ usage: `/${b.name.toLowerCase()} reload`, description: "Reload the config", permission: `${b.name.toLowerCase()}.admin`, whoCanUse: "operators" }] : [],
    permissions: ok ? [{ node: `${b.name.toLowerCase()}.use`, description: "Use the effect", default: "true" }] : [],
    config: ok ? [{ key: "freeze.ticks", description: "How long targets stay frozen", default: "140" }] : [],
    warnings: [], files: ok ? b.src.map((f) => ({ path: f.path, size: f.text.length })).concat([{ path: "build.gradle.kts", size: 800 }]) : [],
    safety: ok ? { verdict: "pass", findings: [] } : null, events: ev, queuePosition: status === "queued" ? 1 : 0,
    finishedAt: ok ? at(T.scanning) : null,
  };
}
function live(b, q) {
  const status = stageAt(b);
  if (status === "succeeded" || status === "failed") return { live: false, status, files: [], draft: null };
  const total = b.src.reduce((n, f) => n + f.text.length, 0);
  const written = status === "coding" ? Math.floor(codingProgress(b) * total) : status === "queued" || status === "planning" ? 0 : total;
  let left = written;
  const files = [];
  let draft = null;
  b.src.forEach((f, i) => {
    if (left >= f.text.length) { files.push({ path: f.path, size: f.text.length, hash: hash(f.text) }); left -= f.text.length; }
    else if (left > 0 || (status === "coding" && !draft)) {
      if (!draft) {
        const n = left; left = 0;
        const from = q.get("draft") === f.path && Number(q.get("seq")) === i ? Math.min(Number(q.get("from") || 0), n) : 0;
        draft = { path: f.path, op: "write", seq: i, from, text: f.text.slice(from, n), total: f.text.length, done: false };
      }
    }
  });
  return { live: true, status, files, draft };
}

createServer(async (req, res) => {
  const u = new URL(req.url, "http://x");
  const send = (code, body, type = "application/json") => { res.writeHead(code, { "Content-Type": type }); res.end(type === "application/json" ? JSON.stringify(body) : body); };
  if (u.pathname === "/health") return send(200, { ok: true, mock: true });
  if (req.headers.authorization !== `Bearer ${KEY}`) return send(401, { error: "unauthorized" });
  const m = u.pathname.match(/^\/builds(?:\/([^/]+))?(?:\/(.*))?$/);
  if (!m) return send(404, { error: "nf" });
  if (req.method === "POST" && !m[1]) {
    let body = ""; for await (const c of req) body += c;
    const j = JSON.parse(body || "{}");
    const name = j.pluginName || nameFor(j.changeRequest ? (builds.get(j.baseBuildId)?.prompt ?? j.prompt) : j.prompt);
    const b = { id: j.id, prompt: j.prompt, changeRequest: j.changeRequest || null, mcVersion: j.mcVersion, name, tagline: j.tagline || `${name} for Paper ${j.mcVersion}`, created: j.done ? Date.now() - 600_000 : Date.now(), done: !!j.done, cancelled: false };
    b.src = sourcesFor(name, j.prompt);
    builds.set(b.id, b);
    return send(202, view(b));
  }
  const b = builds.get(m[1]);
  if (!b) return send(404, { error: "no such build" });
  if (!m[2]) return send(200, view(b));
  if (m[2] === "cancel") { b.cancelled = true; return send(200, { ok: true }); }
  if (m[2] === "live") return send(200, live(b, u.searchParams));
  if (m[2] === "source") { const f = b.src.find((x) => x.path === u.searchParams.get("path")); return f ? send(200, f.text, "text/plain") : send(404, { error: "nf" }); }
  if (m[2] === "artifact") return send(200, jarBytes(b), "application/java-archive");
  if (m[2] === "source.zip") return send(200, Buffer.from("PK mock source zip"), "application/zip");
  send(404, { error: "nf" });
}).listen(PORT, "127.0.0.1", () => console.log("mock modbuilder on", PORT));

