// THROWAWAY seed for node-2's per-worktree DB (wt_cyrus_v5). Never run against prod: it refuses
// any DATABASE_URL that isn't the node-2 agent cluster. One preview user who passes the Cyrus gate
// (Setting preview_access_emails_modbuilder), a token grant, a game server to install to, and a few
// finished builds pulled in through the portal's own syncBuild from the local mock service.
import { createHash } from "node:crypto";
import { writeFileSync } from "node:fs";
import { SignJWT } from "jose";
import { db } from "../lib/db";
import { syncBuild } from "../lib/modbuilder/store";
import { creditTokens } from "../lib/cyrus/tokens/ledger";

const MOCK = process.env.MODBUILDER_URL || "http://127.0.0.1:7399";
const KEY = process.env.MODBUILDER_API_KEY || "local-mock-key";
const EMAIL = "cyrus-preview@nxeon.test";

async function main() {
  const url = process.env.DATABASE_URL ?? "";
  if (!/127\.0\.0\.1:5433\/wt_/.test(url)) throw new Error("refusing: not the node-2 throwaway DB");
  await db.setting.upsert({ where: { key: "preview_access_emails_modbuilder" }, update: { value: EMAIL }, create: { key: "preview_access_emails_modbuilder", value: EMAIL } });
  await db.modBuild.deleteMany({});
  const old = await db.user.findUnique({ where: { email: EMAIL } });
  if (old) {
    await db.cyrusTokenReservation.deleteMany({ where: { userId: old.id } }).catch(() => {});
    await db.userSession.deleteMany({ where: { userId: old.id } }).catch(() => {});
  }
  const user = old ?? (await db.user.create({ data: { email: EMAIL, passwordHash: "x", name: "Cyrus Preview", role: "CUSTOMER", emailVerifiedAt: new Date(), heardAboutUs: "other", balanceCents: 2500 } as never }));
  await creditTokens({ userId: user.id, amount: 1240, kind: "grant", source: "admin", idemKey: `verify-grant-${user.id}`, note: "verification grant", expiresAt: new Date(Date.now() + 80 * 86_400_000) });

  // finished builds the mock knows about
  const mk = async (id: string, prompt: string, minutesAgo: number, extra: Record<string, unknown> = {}, svc: Record<string, unknown> = {}) => {
    await fetch(`${MOCK}/builds`, { method: "POST", headers: { Authorization: `Bearer ${KEY}`, "Content-Type": "application/json" }, body: JSON.stringify({ id, prompt, mcVersion: "1.21.11", done: true, ...svc }) });
    const row = await db.modBuild.create({ data: { id, userId: user.id, prompt, mcVersion: "1.21.11", rootBuildId: (extra.rootBuildId as string) ?? id, createdAt: new Date(Date.now() - minutesAgo * 60_000), ...extra } as never });
    await syncBuild(row);
  };
  await mk("mbseedfrost01", "A frost greatsword: a custom netherite sword that freezes and slows enemies on critical hits", 300, { cyrus: { model: "saka", title: "Frostbite Blade" } }, { pluginName: "FrostbiteBlade", tagline: "Freezes and slows what it crits" });
  await mk("mbseedfrost02", "A frost greatsword: a custom netherite sword that freezes and slows enemies on critical hits", 200, { baseBuildId: "mbseedfrost01", rootBuildId: "mbseedfrost01", changeRequest: "Add a short ice trail behind the player", cyrus: { model: "saka" } }, { pluginName: "FrostbiteBlade", tagline: "Now with an ice trail", changeRequest: "Add a short ice trail behind the player" });
  await mk("mbseedshop01", "A coin shop economy: coins for mob kills, /pay, /baltop and a chest menu shop", 120, { cyrus: { model: "katara" } }, { pluginName: "CoinShop", tagline: "Coins, /pay and a chest-menu shop" });
  await mk("mbseedquest01", "A daily quest board: 3 random quests a day with rewards and a chest menu", 60, { cyrus: { model: "yakko" } }, { pluginName: "QuestBoard", tagline: "Daily quests with rewards" });

  const token = await new SignJWT({ sub: user.id, sv: 0, typ: "session" }).setProtectedHeader({ alg: "HS256" }).setIssuedAt().setExpirationTime("2d").sign(new TextEncoder().encode(process.env.AUTH_SECRET!));
  await db.userSession.create({ data: { userId: user.id, tokenHash: createHash("sha256").update(token).digest("hex") } });
  writeFileSync(".cyrus-verify/session.json", JSON.stringify({ userId: user.id, token }));
  console.log("seeded", user.id, (await db.modBuild.findMany({ select: { id: true, status: true, jarName: true } })).map((b) => `${b.id}:${b.status}:${b.jarName}`).join(" "));
}
main().then(() => process.exit(0), (e) => { console.error(e); process.exit(1); });

