// THROWAWAY Playwright run ON node-2 (devhost run). Real Chromium, real time (no virtual time),
// against the node-2 dev server. SHOTS=portal|cyrus  BASE=http://127.0.0.1:<port>  OUT=dir
import { chromium } from "playwright";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";

const BASE = process.env.BASE;
const OUT = process.env.OUT || ".cyrus-verify/shots";
const WHICH = process.env.SHOTS || "cyrus";
const ONLY = (process.env.ONLY || "").split(",").filter(Boolean);
const { token } = JSON.parse(readFileSync(".cyrus-verify/session.json", "utf8"));
mkdirSync(OUT, { recursive: true });
const log = [];
const note = (...a) => { const l = a.join(" "); log.push(l); console.log(l); };

const browser = await chromium.launch({ args: ["--disable-dev-shm-usage", "--use-angle=swiftshader", "--enable-unsafe-swiftshader", "--ignore-gpu-blocklist"] });
async function ctx(w, theme) {
  const mobile = w < 600;
  const c = await browser.newContext({ viewport: { width: w, height: mobile ? 844 : 900 }, deviceScaleFactor: 1, isMobile: mobile, hasTouch: mobile });
  const host = new URL(BASE).hostname;
  await c.addCookies([{ name: "nxeon_session", value: token, domain: host, path: "/" }, { name: "nxeon_authed", value: "1", domain: host, path: "/" }]);
  await c.addInitScript((t) => {
    try {
      localStorage.setItem("nx-theme", t);
      // dismiss first-run popups the portal shows a fresh account
      for (const k of ["nx-whatsnew-seen", "nx-tour-done", "heard-about-us-dismissed", "promo-trial-dismissed"]) localStorage.setItem(k, "1");
    } catch {}
  }, theme);
  return c;
}
async function go(page, url) {
  for (let i = 0; i < 8; i++) {
    try {
      const r = await page.goto(BASE + url, { waitUntil: "domcontentloaded", timeout: 240000 });
      note("GET", url, r?.status());
      return r;
    } catch (e) {
      if (i === 7) throw e;
      await page.waitForTimeout(8000);
    }
  }
}
async function closePopups(page) {
  for (const name of ["Got it", "Close", "Not now", "Skip", "Dismiss"]) {
    const b = page.getByRole("button", { name, exact: true });
    if ((await b.count()) && (await b.first().isVisible().catch(() => false))) await b.first().click().catch(() => {});
  }
}
const shot = async (page, name, opts = {}) => {
  await page.waitForTimeout(opts.wait ?? 900);
  await page.screenshot({ path: `${OUT}/${name}.png`, fullPage: !!opts.full });
  note("shot", name);
};
const want = (k) => !ONLY.length || ONLY.includes(k);

if (WHICH === "portal") {
  for (const [theme, w] of [["dark", 1440], ["light", 1440], ["dark", 390]]) {
    const c = await ctx(w, theme);
    const p = await c.newPage();
    p.on("pageerror", (e) => note("PAGEERROR", e.message));
    for (const url of ["/dashboard", "/dashboard/services"]) {
      await go(p, url);
      await p.waitForLoadState("networkidle", { timeout: 120000 }).catch(() => {});
      await closePopups(p);
      await shot(p, `${process.env.TAG || "portal"}${url.replace(/\//g, "_")}-${theme}-${w}`, { wait: 2500 });
    }
    await c.close();
  }
} else {
  const studioReady = async (p) => {
    await p.waitForSelector(".cyrus-root .stage", { timeout: 240000 });
    await p.waitForTimeout(4500); // shader compile (swiftshader) + spring-in
    await closePopups(p);
  };
  for (const [theme, w] of [["dark", 1440], ["light", 1440], ["dark", 390], ["light", 390]]) {
    const tag = `${theme}-${w}`;
    const c = await ctx(w, theme);
    const p = await c.newPage();
    p.on("pageerror", (e) => note("PAGEERROR", tag, e.message));
    p.on("console", (m) => { if (m.type() === "error") note("CONSOLE", tag, m.text().slice(0, 300)); });
    // 1. network (server-rendered through the real route)
    const r = await go(p, "/dashboard/cyrus");
    const html = await r.text();
    note("SSR", tag, html.includes("cyrus-root") ? "has .cyrus-root" : "MISSING .cyrus-root", html.includes("nx-shell-root") ? "+ portal shell" : "NO portal shell");
    await studioReady(p);
    if (want("network")) await shot(p, `01-network-${tag}`);
    if (w >= 1000 && theme === "dark") {
      // 2. Ctrl+K palette
      if (want("palette")) {
        await p.keyboard.press("Control+k");
        await p.waitForTimeout(500);
        await p.keyboard.type("frost");
        await shot(p, `06-command-palette-${tag}`, { wait: 700 });
        await p.keyboard.press("Escape");
      }
      // 3. Add game dialog (dashed branch)
      if (want("addgame")) {
        const ghost = p.locator(".node.is-ghost .g-orb");
        if (await ghost.count()) await ghost.first().click({ force: true });
        else await p.getByRole("button", { name: /Add game/ }).first().click();
        await p.waitForTimeout(700);
        await p.locator('input').first().fill("Stardew Valley").catch(() => {});
        await shot(p, `05-add-game-dialog-${tag}`);
        await p.keyboard.press("Escape");
        await p.waitForTimeout(400);
      }
      // 4. token UI: chip + modal with the real balance / plan
      if (want("tokens")) {
        const chip = p.locator(".cyt-chip").first();
        note("token chip:", (await chip.innerText().catch(() => "MISSING")).replace(/\s+/g, " "));
        await chip.click().catch(() => {});
        await p.waitForSelector(".cyt-modal", { timeout: 30000 }).catch(() => note("token modal missing"));
        await shot(p, `11-tokens-modal-${tag}`, { wait: 1200 });
        await p.keyboard.press("Escape");
        await p.locator(".cy-modal-back").first().click({ position: { x: 5, y: 5 } }).catch(() => {});
        await p.waitForTimeout(400);
      }
      // 5. a real mod (seeded): preview panel with real code from the build service
      if (want("realmod")) {
        await p.locator(".pill", { hasText: "Frostbite Blade" }).first().click({ force: true });
        await p.waitForTimeout(2500);
        await shot(p, `12-real-mod-code-${tag}`, { wait: 1500 });
        await p.getByRole("tab", { name: /Versions/ }).click().catch(() => {});
        await shot(p, `13-real-mod-versions-${tag}`);
        await p.getByRole("tab", { name: /Notes/ }).click().catch(() => {});
        await shot(p, `14-real-mod-notes-${tag}`);
        await p.getByRole("button", { name: "Deploy" }).click().catch(() => {});
        await shot(p, `15-install-modal-${tag}`, { wait: 900 });
        await p.keyboard.press("Escape");
        await p.locator(".cy-modal-back").first().click({ position: { x: 5, y: 5 } }).catch(() => {});
        await p.keyboard.press("Escape"); await p.keyboard.press("Escape"); await p.keyboard.press("Escape");
        await p.waitForTimeout(800);
      }
      // 6. model picker (token ranges + locks)
      if (want("models")) {
        await p.locator(".prompt-shell button[aria-haspopup=listbox]").first().click().catch(() => {});
        await shot(p, `16-model-picker-${tag}`, { wait: 700 });
        await p.keyboard.press("Escape");
      }
      // 7. REAL forge (Minecraft): thinking, then code streaming from the (local) build service
      if (want("forge-real")) {
        await p.getByRole("button", { name: "Recenter on the core" }).click().catch(() => {});
        await p.waitForTimeout(600);
        const ta = p.locator("textarea.prompt-textarea");
        await ta.click();
        await ta.fill("A frost axe for Minecraft that freezes and slows enemies on critical hits, with a config for the freeze time");
        await shot(p, `17-prompt-typed-estimate-${tag}`, { wait: 800 });
        await ta.press("Enter");
        await p.waitForTimeout(1600);
        await shot(p, `03-thinking-real-${tag}`, { wait: 200 });
        await p.waitForTimeout(9000);
        await shot(p, `04-forging-real-code-stream-${tag}`, { wait: 200 });
        await p.waitForTimeout(9000);
        await shot(p, `04b-forging-real-code-stream-${tag}`, { wait: 200 });
        await p.waitForSelector("text=/is ready/", { timeout: 120000 }).catch(() => note("real forge: no ready toast"));
        await shot(p, `18-real-forge-done-${tag}`, { wait: 1500 });
        note("token chip after:", (await p.locator(".cyt-chip").first().innerText().catch(() => "MISSING")).replace(/\s+/g, " "));
        await p.keyboard.press("Escape"); await p.keyboard.press("Escape"); await p.keyboard.press("Escape");
      }
      // 8. TEMPLATE forge (Valheim)
      if (want("forge-template")) {
        await p.getByRole("button", { name: "Recenter on the core" }).click().catch(() => {});
        await p.waitForTimeout(600);
        const ta = p.locator("textarea.prompt-textarea");
        await ta.click();
        await ta.fill("A frost axe for Valheim that freezes and slows what it hits");
        await shot(p, `19-template-prompt-${tag}`, { wait: 600 });
        await ta.press("Enter");
        await p.waitForTimeout(1500);
        await shot(p, `03-thinking-template-${tag}`, { wait: 200 });
        await p.waitForTimeout(5500);
        await shot(p, `04-forging-template-code-stream-${tag}`, { wait: 200 });
        await p.waitForSelector("text=/forged/", { timeout: 120000 }).catch(() => note("template forge: no forged toast"));
        await shot(p, `20-template-forge-done-${tag}`, { wait: 1200 });
      }
    }
    if (w < 1000 && want("mobile-forge") && theme === "dark") {
      await p.locator(".pill", { hasText: "Frostbite Blade" }).first().click({ force: true }).catch(() => {});
      await shot(p, `12-real-mod-code-${tag}`, { wait: 2500 });
    }
    // 9. core gallery + preview (+ aurora is the network background; a close crop below)
    if (want("cores")) {
      await go(p, "/dashboard/cyrus/cores");
      await p.waitForSelector(".cores-page", { timeout: 240000 });
      await p.waitForTimeout(5000);
      await shot(p, `07-cores-gallery-${tag}`);
      if (theme === "dark") {
        await p.locator(".cores-page").evaluate((el) => el.scrollTo(0, 700));
        await shot(p, `08-cores-gallery-grid-${tag}`, { wait: 3500 });
        await p.locator(".core-card-stage").first().click().catch(() => {});
        await shot(p, `09-core-preview-${tag}`, { wait: 3500 });
        await p.keyboard.press("Escape");
      }
    }
    if (want("aurora") && theme === "dark" && w >= 1000) {
      await go(p, "/dashboard/cyrus");
      await studioReady(p);
      await p.addStyleTag({ content: ".cyrus-root .world, .cyrus-root .stage canvas, .cyrus-root header, .cyrus-root aside { visibility: hidden !important; } .cyrus-root .fixed.bottom-4, .cyrus-root .fixed.bottom-6 { visibility: hidden !important; }" });
      await shot(p, `10-aurora-background-${tag}`, { wait: 1500 });
    }
    // 10. the rest of the portal after leaving Cyrus by a soft navigation (no style leaks)
    if (want("leak") && w >= 1000) {
      await go(p, "/dashboard/cyrus");
      await studioReady(p);
      await p.evaluate(() => { const a = document.querySelector('a[href="/dashboard/services"]'); if (a) (a).click(); });
      await p.waitForURL(/\/dashboard\/services/, { timeout: 120000 }).catch(() => note("soft nav failed"));
      await p.waitForTimeout(4000);
      await shot(p, `21-services-after-cyrus-softnav-${tag}`);
    }
    await c.close();
  }
}
writeFileSync(`${OUT}/log.txt`, log.join("\n") + "\n");
await browser.close();

