"use client";

// One tiny client store for the Cyrus token UI, shared by the chip, the composer
// estimate, the model locks and the modal (no provider to wire into Cyrus).
import { useSyncExternalStore } from "react";
import type { TokenState } from "@/lib/cyrus/tokens/view";

export type TokensReason = "insufficient_tokens" | "model_locked" | "daily_cap" | null;
export type TokensTab = "plans" | "topup" | "history";
type Snap = { state: TokenState | null; loading: boolean; open: boolean; tab: TokensTab; reason: TokensReason; notice: string | null };

let snap: Snap = { state: null, loading: false, open: false, tab: "plans", reason: null, notice: null };
const subs = new Set<() => void>();
const emit = (patch: Partial<Snap>) => { snap = { ...snap, ...patch }; subs.forEach((f) => f()); };
let inflight: Promise<void> | null = null;
let timer: number | undefined;

export const cyrusTokens = {
  get: () => snap,
  subscribe(f: () => void) {
    subs.add(f);
    if (subs.size === 1) start();
    return () => { subs.delete(f); if (!subs.size) stop(); };
  },
  refresh(): Promise<void> {
    if (inflight) return inflight;
    emit({ loading: true });
    inflight = fetch("/api/cyrus/tokens", { cache: "no-store" })
      .then(async (r) => { if (r.ok) emit({ state: (await r.json()) as TokenState }); else if (r.status === 404) emit({ state: null }); })
      .catch(() => undefined)
      .finally(() => { inflight = null; emit({ loading: false }); });
    return inflight;
  },
  open(opts: { tab?: TokensTab; reason?: TokensReason } = {}) {
    emit({ open: true, tab: opts.tab ?? (opts.reason === "model_locked" ? "plans" : opts.reason ? "plans" : snap.tab), reason: opts.reason ?? null });
    void cyrusTokens.refresh();
  },
  close() { emit({ open: false, reason: null }); },
  setTab(tab: TokensTab) { emit({ tab }); },
  notify(notice: string | null) { emit({ notice }); },
  /** Call with a failed build-create response body: opens the modal for token/plan errors. */
  handleBuildError(j: { code?: string } | null | undefined): boolean {
    const c = j?.code;
    if (c === "insufficient_tokens" || c === "model_locked" || c === "daily_cap") {
      if (c !== "daily_cap") cyrusTokens.open({ reason: c });
      void cyrusTokens.refresh();
      return true;
    }
    return false;
  },
};

const tick = () => { if (document.visibilityState === "visible") void cyrusTokens.refresh(); };
function start() {
  void cyrusTokens.refresh();
  timer = window.setInterval(tick, 20_000);
  window.addEventListener("focus", tick);
}
function stop() { window.clearInterval(timer); window.removeEventListener("focus", tick); }

export function useCyrusTokens(): Snap {
  return useSyncExternalStore(cyrusTokens.subscribe, cyrusTokens.get, () => SERVER);
}
const SERVER: Snap = { state: null, loading: false, open: false, tab: "plans", reason: null, notice: null };

export const fmtTokens = (n: number) => Math.round(n).toLocaleString("en-US");
export const fmtMoney = (cents: number) => `$${(cents / 100).toFixed(cents % 100 ? 2 : 0)}`;

